INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_001','World kitchen 001','Emmer Pasta Aglio e Olio','emmer-pasta-aglio-e-olio','Kathiya emmer pasta with slow-gilded garlic and chilli, loosened with starchy pasta water into a glossy sauce.',10,15,2,'["vegetarian","vegan"]','published','rcv_world_001_1','2026-08-16T09:00:00Z','Emmer Pasta Aglio e Olio — True Grit','Kathiya emmer pasta with slow-gilded garlic and chilli, loosened with starchy pasta water into a glossy sauce.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','emmer pasta, aglio e olio, Italian, whole wheat pasta',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/whole-wheat-pasta.webp','Emmer Pasta Aglio e Olio, made with True Grit staples',NULL,'Italian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_001_1','rcp_world_001',1,'{"steps":["Bring four litres of water to a rolling boil and salt it heavily.","Slice the garlic thinly and lengthways so that it colours evenly rather than catching.","Add the pasta and set a timer for two minutes under the packet time.","Warm the oil with the garlic and chillies in a wide pan over the lowest heat.","Cook until the garlic is pale gold, then pull the pan off the heat entirely.","Reserve a full cup of the starchy cooking water before you drain anything.","Drain the pasta while the centre still gives a distinct, firm bite.","Return the pan to low heat, add the pasta and a splash of the reserved water.","Toss hard until the oil and water emulsify into a sauce that coats every strand.","Finish off the heat with parsley, sesame seeds and pepper, then serve at once."],"blocks":[{"id":"blk_world_001_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Aglio e olio lives or dies on two things: garlic that turns pale gold rather than brown, and enough starchy water to bind oil into a sauce.","Emmer pasta has a shorter window between firm and soft than refined durum, so pull it early and let it finish in the pan."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_001','Emmer Pasta Aglio e Olio','emmer-pasta-aglio-e-olio','Kathiya emmer pasta with slow-gilded garlic and chilli, loosened with starchy pasta water into a glossy sauce.','emmer pasta, aglio e olio, Italian, whole wheat pasta');
