INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_002','World kitchen 002','Banshi Durum Pasta with Slow Tomato and Basil','durum-pasta-slow-tomato-basil','A forty-minute tomato sauce built on Banshi durum pasta, where the only technique is refusing to rush the reduction.',15,50,4,'["vegetarian"]','published','rcv_world_002_1','2026-08-16T09:00:00Z','Banshi Durum Pasta with Slow Tomato and Basil — True Grit','A forty-minute tomato sauce built on Banshi durum pasta, where the only technique is refusing to rush the reduction.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','durum pasta, tomato basil sauce, Italian, Banshi wheat',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/whole-wheat-pasta.webp','Banshi Durum Pasta with Slow Tomato and Basil, made with True Grit staples',NULL,'Italian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_002_1','rcp_world_002',1,'{"steps":["Warm the oil and cook the onion gently until soft and translucent, not coloured.","Add the garlic and cook for one minute, only until the raw edge disappears.","Tip in the tomatoes with a good pinch of salt and stir once.","Bring to a bubble, then drop the heat until the surface barely moves.","Simmer uncovered for forty minutes, stirring occasionally and scraping the base.","Taste and correct: salt first, then a little sugar only if it is sharp.","Boil the pasta in heavily salted water, stopping two minutes short of the packet time.","Reserve a cup of pasta water, then drain the pasta without rinsing it.","Combine pasta and sauce in the pan, loosening with pasta water until it flows.","Tear in the basil off the heat so its aroma survives, then serve immediately."],"blocks":[{"id":"blk_world_002_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["A long, quiet simmer is what separates a tomato sauce from tomato soup poured over pasta. Forty minutes at a bare bubble concentrates a sweetness no sugar reproduces.","Salt the pasta water properly. It is the only chance the pasta itself gets to be seasoned from the inside."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_002','Banshi Durum Pasta with Slow Tomato and Basil','durum-pasta-slow-tomato-basil','A forty-minute tomato sauce built on Banshi durum pasta, where the only technique is refusing to rush the reduction.','durum pasta, tomato basil sauce, Italian, Banshi wheat');
