INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_003','World kitchen 003','Emmer Pasta Cacio e Pepe','emmer-pasta-cacio-e-pepe','Three ingredients and one hazard: cheese that seizes into strings the moment the pan is too hot.',5,15,2,'["vegetarian"]','published','rcv_world_003_1','2026-08-16T09:00:00Z','Emmer Pasta Cacio e Pepe — True Grit','Three ingredients and one hazard: cheese that seizes into strings the moment the pan is too hot.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','cacio e pepe, emmer pasta, Roman pasta, black pepper',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/whole-wheat-pasta.webp','Emmer Pasta Cacio e Pepe, made with True Grit staples',NULL,'Italian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_003_1','rcp_world_003',1,'{"steps":["Crack the peppercorns coarsely so they release aroma without turning to dust.","Toast the cracked pepper in a dry pan for thirty seconds until fragrant.","Boil the pasta in less water than usual so the starch concentrates.","Grate the cheese as finely as you can, because coarse shreds clump.","Ladle hot pasta water into the pepper pan and let it stop bubbling hard.","Drain the pasta two minutes early and add it to the warm pepper water.","Take the pan off the heat entirely before any cheese goes near it.","Add the cheese in three additions, tossing hard between each one.","Loosen with more pasta water until the sauce turns creamy and coats the strands.","Serve straight away, because this sauce tightens as soon as it cools."],"blocks":[{"id":"blk_world_003_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Cacio e pepe fails in exactly one way, and it is heat. Cheese meeting a hot pan clumps into rubber instead of melting into cream.","Work off the heat, use water that has stopped steaming furiously, and add the cheese in stages rather than all at once."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_003','Emmer Pasta Cacio e Pepe','emmer-pasta-cacio-e-pepe','Three ingredients and one hazard: cheese that seizes into strings the moment the pan is too hot.','cacio e pepe, emmer pasta, Roman pasta, black pepper');
