INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_004_1','rcp_world_004',1,'{"steps":["Bring the milk to a bare simmer with the salt and the nutmeg.","Rain the semolina in slowly while whisking hard to prevent any lumps forming.","Cook for ten minutes over low heat, stirring constantly as it thickens.","Stop when a spoon dragged across the base leaves a clear trail behind it.","Beat in half the butter, half the cheese and both egg yolks off the heat.","Spread the paste two centimetres thick on an oiled tray and smooth the top.","Chill for at least an hour until completely firm to the touch.","Cut into rounds with a glass and overlap them in a buttered dish.","Dot with the remaining butter and scatter over the rest of the cheese.","Bake at 200C for twenty minutes until the tops are blistered and golden."],"blocks":[{"id":"blk_world_004_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["These are not the potato dumplings most people picture. Semolina is cooked into a thick paste, spread to set, then cut into rounds and baked.","The setting stage is not optional. Warm paste will not cut cleanly, and rounds that tear will not crisp at the edges."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_004','Semolina Gnocchi alla Romana','semolina-gnocchi-alla-romana','Set semolina cut into discs and baked until the edges crisp, nothing like the potato dumpling of the same name.','gnocchi alla romana, semolina, baked semolina, Italian');
