INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_005','World kitchen 005','Italian Lentil Soup with Broken Pasta','italian-lentil-soup-with-pasta','Pasta snapped into short lengths and cooked in the soup itself, so its starch does the thickening.',15,45,4,'["vegetarian","vegan"]','published','rcv_world_005_1','2026-08-16T09:00:00Z','Italian Lentil Soup with Broken Pasta — True Grit','Pasta snapped into short lengths and cooked in the soup itself, so its starch does the thickening.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','lentil soup, pasta e lenticchie, Italian soup, red lentils',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Italian Lentil Soup with Broken Pasta, made with True Grit staples',NULL,'Italian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_005_1','rcp_world_005',1,'{"steps":["Warm the oil and sweat the onion, carrot and celery for ten slow minutes.","Add the garlic, rosemary and bay, cooking one minute until fragrant.","Stir in the tomatoes and cook until they darken and lose their raw edge.","Rinse the lentils and add them with the stock, then bring to the boil.","Simmer covered for twenty-five minutes until the lentils are tender but whole.","Snap the pasta into short lengths directly into the pot and stir once.","Cook uncovered until the pasta is done, roughly ten further minutes.","Stir often now, because the thickening soup catches easily on the base.","Fish out the rosemary stalk and bay leaf before they overwhelm the pot.","Season, loosen with hot stock to the thickness you want, and finish with oil."],"blocks":[{"id":"blk_world_005_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Cooking the pasta in the soup rather than separately is the whole point. The starch it sheds is what turns broth into something with body.","It also means the soup keeps thickening as it stands, so hold back a little stock to loosen it before serving."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_005','Italian Lentil Soup with Broken Pasta','italian-lentil-soup-with-pasta','Pasta snapped into short lengths and cooked in the soup itself, so its starch does the thickening.','lentil soup, pasta e lenticchie, Italian soup, red lentils');
