INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_006_1','rcp_world_006',1,'{"steps":["Rinse the lentils and put them in a pan with cold unsalted water.","Add the whole carrot, bay and thyme to perfume the pot as it cooks.","Bring to a boil, then simmer gently for twenty-five minutes until just tender.","Test several lentils, because a pot cooks unevenly and averages mislead you.","Whisk the mustard and vinegar together before adding any of the oil.","Add the mustard oil slowly, whisking until the dressing thickens and holds.","Drain the lentils and discard the carrot, bay leaf and thyme stalks.","Tip the hot lentils straight into the dressing with the diced shallots.","Toss and leave for ten minutes so the warm lentils absorb the vinaigrette.","Fold the parsley through, season generously, and serve warm or at room temperature."],"blocks":[{"id":"blk_world_006_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Dress lentils while they are warm. Cold lentils repel a vinaigrette and you end up with dressing pooled at the bottom of the bowl.","Salt only after they are tender. Salted cooking water firms the skins and leaves the centres stubbornly chalky."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_006','French Lentil Salad with Mustard Dressing','french-lentil-salad-mustard-dressing','Whole lentils dressed while still warm so they drink the vinaigrette instead of sitting in it.','French lentil salad, mustard vinaigrette, lentils, cold salad');
