INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_007','World kitchen 007','French Sesame Sable Biscuits','french-sesame-sable-biscuits','A sandy French shortbread rolled in sesame seeds, where overworking the dough is the only real mistake.',20,15,24,'["vegetarian"]','published','rcv_world_007_1','2026-08-16T09:00:00Z','French Sesame Sable Biscuits — True Grit','A sandy French shortbread rolled in sesame seeds, where overworking the dough is the only real mistake.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','sable biscuits, sesame, French baking, shortbread',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','French Sesame Sable Biscuits, made with True Grit staples',NULL,'French');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_007_1','rcp_world_007',1,'{"steps":["Rub the cold butter into the flour and salt until it looks like coarse sand.","Stir the sugar and the plain sesame seeds through the crumb mixture evenly.","Add the yolks and vanilla, bringing the dough together with as few strokes as possible.","Stop the moment it coheres, even if it still looks slightly ragged.","Roll into two logs about five centimetres across on a sheet of parchment.","Chill the logs for at least two hours, or overnight if you can.","Roll each cold log firmly in the roasted sesame seeds to coat the sides.","Slice into rounds a centimetre thick with a single confident cut each time.","Bake at 170C for fifteen minutes until the edges are just turning gold.","Cool completely on the tray, because they are fragile while still warm."],"blocks":[{"id":"blk_world_007_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Sable means sandy, and that texture comes from handling the dough as little as possible. Every extra minute of mixing develops gluten and moves you towards a biscuit.","Chill the log properly before slicing. Soft dough drags under the knife and the rounds lose their edges."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_007','French Sesame Sable Biscuits','french-sesame-sable-biscuits','A sandy French shortbread rolled in sesame seeds, where overworking the dough is the only real mistake.','sable biscuits, sesame, French baking, shortbread');
