INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_008','World kitchen 008','Spanish Smoked Paprika Field Pea Stew','spanish-chickpea-free-pea-stew','White field peas stand in for chickpeas in a smoky, slow potaje built on paprika and good oil.',20,90,6,'["vegetarian","vegan","gluten free"]','published','rcv_world_008_1','2026-08-16T09:00:00Z','Spanish Smoked Paprika Field Pea Stew — True Grit','White field peas stand in for chickpeas in a smoky, slow potaje built on paprika and good oil.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','Spanish stew, smoked paprika, field peas, potaje',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/white-field-peas.webp','Spanish Smoked Paprika Field Pea Stew, made with True Grit staples',NULL,'Spanish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_008_1','rcp_world_008',1,'{"steps":["Drain the soaked peas and simmer them in fresh unsalted water with the bay.","Cook for about an hour until tender, topping up with hot water as needed.","Warm the oil in a second pan and cook the onion until deeply soft.","Add the garlic and cook briefly, then take the pan off the heat.","Stir the smoked paprika into the off-heat oil so it blooms without scorching.","Return to low heat, add the grated tomato and cook down for ten minutes.","Tip this base into the peas along with the potato chunks and stir well.","Simmer for twenty minutes until the potatoes are tender and the broth thickens.","Stir the spinach through and cook only until it collapses into the stew.","Season with salt now and rest the pot ten minutes before serving."],"blocks":[{"id":"blk_world_008_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Smoked paprika is the whole personality of this stew, and it burns in seconds. Add it off the heat, always, and stir it into fat rather than a dry pan.","Field peas need an overnight soak. Without it you get a pot where some are creamy and others are still hard."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_008','Spanish Smoked Paprika Field Pea Stew','spanish-chickpea-free-pea-stew','White field peas stand in for chickpeas in a smoky, slow potaje built on paprika and good oil.','Spanish stew, smoked paprika, field peas, potaje');
