INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_009','World kitchen 009','Spanish Sesame and Almond Picada','spanish-picada-sesame-almond','The pounded paste Catalan cooks stir into a stew at the last minute to thicken and sharpen it at once.',15,10,8,'["vegetarian","vegan","gluten free"]','published','rcv_world_009_1','2026-08-16T09:00:00Z','Spanish Sesame and Almond Picada — True Grit','The pounded paste Catalan cooks stir into a stew at the last minute to thicken and sharpen it at once.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','picada, Spanish sauce, sesame, almond, thickener',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Spanish Sesame and Almond Picada, made with True Grit staples',NULL,'Spanish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_009_1','rcp_world_009',1,'{"steps":["Fry the bread in a little of the oil until crisp and golden on both sides.","Fry the almonds in the same pan for two minutes until lightly coloured.","Fry the whole garlic cloves briefly, taking them out before they darken.","Toast the saffron for a few seconds in the residual pan heat only.","Pound the almonds and garlic in a mortar until they break into rough rubble.","Add the bread and sesame seeds and keep pounding to a coarse paste.","Work in the parsley and saffron so the colour streaks through the paste.","Loosen with the vinegar and the remaining oil to a thick spoonable consistency.","Stir into a stew five minutes before the end of its cooking time.","Keep any leftover picada refrigerated under a film of oil for a week."],"blocks":[{"id":"blk_world_009_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["A picada is not a sauce you serve. It is stirred into something else in the final five minutes, where it thickens the liquid and lifts the flavour together.","Pound rather than blend if you can. A mortar bruises the nuts and releases oil; a blade chops them and the texture goes flat."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_009','Spanish Sesame and Almond Picada','spanish-picada-sesame-almond','The pounded paste Catalan cooks stir into a stew at the last minute to thicken and sharpen it at once.','picada, Spanish sauce, sesame, almond, thickener');
