INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_010','World kitchen 010','Portuguese Lentil and Rice Soup','portuguese-lentil-rice-soup','A plain, sustaining soup where a slick of good oil poured in at the table does most of the flavouring.',15,40,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_010_1','2026-08-16T09:00:00Z','Portuguese Lentil and Rice Soup — True Grit','A plain, sustaining soup where a slick of good oil poured in at the table does most of the flavouring.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','Portuguese soup, lentil rice soup, sopa de lentilhas',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Portuguese Lentil and Rice Soup, made with True Grit staples',NULL,'Portuguese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_010_1','rcp_world_010',1,'{"steps":["Warm the oil and cook the onion and carrot together for eight minutes.","Add the garlic and bay leaf, stirring for a minute until aromatic.","Rinse both lentils together and add them with the water to the pot.","Bring to the boil and skim any grey foam that gathers on the surface.","Simmer covered for twenty minutes until the broken lentils have collapsed.","Stir in the rice and cook for a further fifteen minutes, uncovered.","Stir regularly at this stage so the rice does not settle and catch.","Add hot water if the soup thickens past a comfortably spoonable consistency.","Season with salt only once the rice is fully cooked and swelling has stopped.","Serve each bowl with a generous spiral of raw oil poured over the top."],"blocks":[{"id":"blk_world_010_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Portuguese home soup is deliberately unfussy. The finishing oil, poured over each bowl rather than cooked in, is where the flavour arrives.","Broken lentils give body and whole ones give texture, so a mixture of the two makes a better bowl than either alone."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_010','Portuguese Lentil and Rice Soup','portuguese-lentil-rice-soup','A plain, sustaining soup where a slick of good oil poured in at the table does most of the flavouring.','Portuguese soup, lentil rice soup, sopa de lentilhas');
