INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_011','World kitchen 011','Roasted Sesame Tahini','roasted-sesame-tahini','Two ingredients and a patient blender turn roasted sesame seeds into a pourable tahini that beats anything from a jar.',10,10,12,'["vegetarian","vegan","gluten free"]','published','rcv_world_011_1','2026-08-16T09:00:00Z','Roasted Sesame Tahini — True Grit','Two ingredients and a patient blender turn roasted sesame seeds into a pourable tahini that beats anything from a jar.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tahini, sesame paste, Levantine, roasted sesame seeds',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Roasted Sesame Tahini, made with True Grit staples',NULL,'Levantine');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_011_1','rcp_world_011',1,'{"steps":["Warm the plain seeds in a dry pan until nutty and a shade darker.","Spread every seed on a tray and cool them completely to room temperature.","Blend the cooled seeds alone for two minutes, scraping the sides down.","Continue through the dry, crumbly stage without adding any water at all.","Add one teaspoon of sesame oil and blend again for a full minute.","Repeat with more oil, a teaspoon at a time, until the paste pours.","Blend in the salt last so you taste the sesame while adjusting it.","Rest the machine if it grows hot, then finish with a smooth final blend.","Decant into a sterilised jar and refrigerate for up to one month.","Stir separated oil back in before use rather than pouring it away."],"blocks":[{"id":"blk_world_011_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Tahini is sesame seeds and a little oil. Everything else is patience: the paste passes through a dry, crumbly stage that looks like failure and then suddenly loosens.","Do not add water at that stage. Water seizes tahini into a stiff mass; oil, a teaspoon at a time, is what carries it through."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_011','Roasted Sesame Tahini','roasted-sesame-tahini','Two ingredients and a patient blender turn roasted sesame seeds into a pourable tahini that beats anything from a jar.','tahini, sesame paste, Levantine, roasted sesame seeds');
