INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_012','World kitchen 012','Cracked Wheat Tabbouleh','cracked-wheat-tabbouleh','A herb salad that happens to contain grain, using soaked Kathiya daliya rather than cooking it soft.',25,0,4,'["vegetarian","vegan"]','published','rcv_world_012_1','2026-08-16T09:00:00Z','Cracked Wheat Tabbouleh — True Grit','A herb salad that happens to contain grain, using soaked Kathiya daliya rather than cooking it soft.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tabbouleh, cracked wheat, daliya, Levantine salad',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Cracked Wheat Tabbouleh, made with True Grit staples',NULL,'Levantine');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_012_1','rcp_world_012',1,'{"steps":["Rinse the daliya, cover it with cold water and leave twenty minutes.","Drain thoroughly and squeeze the excess water out with clean hands.","Wash and dry the herbs completely, because wet leaves bruise as you chop.","Chop the parsley and mint with a sharp knife rather than tearing them.","Dice the tomatoes and drain them in a sieve so the salad does not flood.","Combine drained daliya, herbs, tomatoes and spring onions in a wide bowl.","Dress with lemon juice and oil, adding the salt only at this point.","Toss gently from underneath so the herbs stay lofty rather than compacting.","Rest ten minutes so the grain takes up the dressing and the lemon.","Taste again before serving and correct the lemon and salt together."],"blocks":[{"id":"blk_world_012_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Tabbouleh is a parsley salad with cracked wheat in it, not a grain salad with parsley on top. The proportions below look wrong and are correct.","The daliya is soaked, never boiled. Cold water and twenty minutes leave it tender with a bite; hot water turns it to porridge."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_012','Cracked Wheat Tabbouleh','cracked-wheat-tabbouleh','A herb salad that happens to contain grain, using soaked Kathiya daliya rather than cooking it soft.','tabbouleh, cracked wheat, daliya, Levantine salad');
