INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_013_1','rcp_world_013',1,'{"steps":["Slice the onions as thinly as you can so they fry evenly.","Fry them in the oil over medium heat, stirring, for twenty minutes.","Lift them out at deep mahogany and drain on paper before they darken further.","Simmer the rinsed lentils in the water for fifteen minutes until half tender.","Stir the cumin and allspice into three tablespoons of the onion oil.","Add the spiced oil and the rinsed rice to the lentils and their liquid.","Cover and cook on the lowest heat for eighteen minutes without lifting the lid.","Rest off the heat, still covered, for a further ten minutes.","Fork through gently, folding in half the crisp onions and the seasoning.","Pile the rest of the onions on top and serve warm or at room temperature."],"blocks":[{"id":"blk_world_013_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The onions are the dish. Fry them well past golden, to a deep mahogany, because that is where the sweetness and the smell come from.","Take them out the moment they hit that colour. Carry-over heat will push them from dark to bitter in under a minute."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
