INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_015','World kitchen 015','Lebanese Tarator Tahini Sauce','lebanese-sesame-tahini-sauce','The sauce that alarms everyone the first time: tahini seizes solid before it turns silky.',10,0,8,'["vegetarian","vegan","gluten free"]','published','rcv_world_015_1','2026-08-16T09:00:00Z','Lebanese Tarator Tahini Sauce — True Grit','The sauce that alarms everyone the first time: tahini seizes solid before it turns silky.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tarator, tahini sauce, Lebanese, sesame sauce',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Lebanese Tarator Tahini Sauce, made with True Grit staples',NULL,'Lebanese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_015_1','rcp_world_015',1,'{"steps":["Crush the garlic with the salt until it becomes a smooth wet paste.","Whisk the tahini and the garlic paste together in a wide bowl.","Add the lemon juice and whisk hard as the mixture stiffens and seizes.","Keep whisking through the thick stage without adding water yet.","Add ice cold water one tablespoon at a time, whisking after each.","Watch the sauce pale and loosen suddenly once enough water is in.","Stop when it ribbons off the whisk and holds its line briefly.","Season with the cumin and more salt, tasting as the acidity settles.","Rest for ten minutes, then check the thickness and loosen if needed.","Finish with parsley and a thread of sesame oil just before serving."],"blocks":[{"id":"blk_world_015_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Tahini thickens dramatically when the first water hits it, and most people panic and stop. Keep going; it loosens into silk on the far side.","Add lemon before water. The acid does part of the loosening and the sauce holds together better for it."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_015','Lebanese Tarator Tahini Sauce','lebanese-sesame-tahini-sauce','The sauce that alarms everyone the first time: tahini seizes solid before it turns silky.','tarator, tahini sauce, Lebanese, sesame sauce');
