INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_016_1','rcp_world_016',1,'{"steps":["Simmer the rinsed lentils in 700 ml water until soft and almost dry.","Stir the semolina into the hot lentils off the heat and cover the pan.","Leave covered twenty minutes so the semolina swells and firms the mixture.","Cook the onions slowly in the oil until deeply soft and golden.","Add tomato paste and spices, frying two minutes to lose the raw taste.","Fold the onion mixture through the lentils while everything is still warm.","Knead by hand for several minutes until smooth and fully cohesive.","Work in the herbs and lemon juice, correcting the salt as you go.","Squeeze walnut-sized portions in your fist so your fingers leave ridges.","Chill briefly and serve cool in lettuce with extra lemon alongside."],"blocks":[{"id":"blk_world_016_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["These are not fried. The semolina goes into the hot lentils off the heat and swells there, which is what makes the mixture hold in the hand.","Shape them while warm but comfortable to touch. Cold mixture cracks; hot mixture will not keep its ridges."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
