INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_017','World kitchen 017','Turkish Sesame Simit Rings','turkish-sesame-simit-rings','Twisted bread rings dipped in grape molasses before their sesame crust, which is what makes them lacquer rather than merely stick.',40,20,8,'["vegetarian","vegan"]','published','rcv_world_017_1','2026-08-16T09:00:00Z','Turkish Sesame Simit Rings — True Grit','Twisted bread rings dipped in grape molasses before their sesame crust, which is what makes them lacquer rather than merely stick.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','simit, sesame bread rings, Turkish bread, wheat flour',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/wheat-flour.webp','Turkish Sesame Simit Rings, made with True Grit staples',NULL,'Turkish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_017_1','rcp_world_017',1,'{"steps":["Mix the yeast and sugar into the warm water and leave until foaming.","Combine the flour and salt, then add the yeast water and the oil.","Knead for ten minutes until the dough is smooth and springs back slowly.","Prove covered in a warm place for one hour, until roughly doubled.","Divide into eight pieces and roll each into a long thin rope.","Fold each rope in half and twist the two strands around each other.","Join the ends into a ring, pinching firmly so they do not unravel.","Thin the molasses with equal water and dip each ring completely.","Press both sides hard into the sesame seeds to load the crust.","Bake at 220C for twenty minutes until deep brown and hollow-sounding."],"blocks":[{"id":"blk_world_017_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The molasses dip is not for sweetness. It is what makes the crust darken and lacquer in the oven, and water alone will not do it.","Press the rings hard into a deep bed of seeds. A light sprinkle falls off in the oven and leaves bald patches."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_017','Turkish Sesame Simit Rings','turkish-sesame-simit-rings','Twisted bread rings dipped in grape molasses before their sesame crust, which is what makes them lacquer rather than merely stick.','simit, sesame bread rings, Turkish bread, wheat flour');
