INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_018','World kitchen 018','Turkish Tarhana-Style Semolina Soup','turkish-tarhana-style-soup','A sour, thick winter soup approximated with semolina and yoghurt when no fermented tarhana is to hand.',10,25,4,'["vegetarian"]','published','rcv_world_018_1','2026-08-16T09:00:00Z','Turkish Tarhana-Style Semolina Soup — True Grit','A sour, thick winter soup approximated with semolina and yoghurt when no fermented tarhana is to hand.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tarhana soup, semolina soup, Turkish, winter soup',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/semolina.webp','Turkish Tarhana-Style Semolina Soup, made with True Grit staples',NULL,'Turkish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_018_1','rcp_world_018',1,'{"steps":["Toast the semolina in the fat over low heat until it smells nutty.","Stir in the tomato and pepper pastes and cook them for two minutes.","Add the hot stock gradually, whisking so no lumps of semolina survive.","Simmer for fifteen minutes, stirring often, until visibly thickened.","Whisk the yoghurt in a bowl until completely smooth and slack.","Ladle hot soup into the yoghurt a little at a time, whisking constantly.","Return the tempered yoghurt to the pot off the heat and stir it through.","Warm gently without letting it reach a boil, or it will split.","Fry the dried mint in a spoonful of hot fat for a few seconds.","Pour the mint butter over each bowl and season generously at the table."],"blocks":[{"id":"blk_world_018_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Real tarhana is fermented for weeks. This is the shortcut version, using yoghurt for the sourness and semolina for the body.","Temper the yoghurt before it enters the pot. Cold yoghurt hitting hot soup splits into curds and there is no unsplitting it."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_018','Turkish Tarhana-Style Semolina Soup','turkish-tarhana-style-soup','A sour, thick winter soup approximated with semolina and yoghurt when no fermented tarhana is to hand.','tarhana soup, semolina soup, Turkish, winter soup');
INSERT INTO recipe_ingredients (id,recipe_id,label,quantity_text,product_id,sort_order) VALUES ('rci_world_018_01','rcp_world_018','Kathiya semolina','80 g',(SELECT id FROM products WHERE slug='semolina-kathiya-wheat'),1);
