INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_019_1','rcp_world_019',1,'{"steps":["Boil the syrup sugar, water and lemon juice five minutes, then cool completely.","Whisk eggs and caster sugar until pale, thick and clearly increased in volume.","Pour in the oil slowly while whisking so the mixture stays emulsified.","Fold in the yoghurt and lemon zest with a spatula, not a whisk.","Combine semolina and baking powder, then fold through in two additions.","Rest the batter twenty minutes so the semolina absorbs moisture and swells.","Bake at 175C for forty-five minutes until a skewer comes out clean.","Pour the cold syrup over the hot cake the moment it leaves the oven.","Leave it to drink the syrup for at least two hours before cutting.","Scatter roasted sesame over the top and cut into diamonds to serve."],"blocks":[{"id":"blk_world_019_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The rule that decides this cake is temperature: cold syrup onto hot cake, or hot syrup onto cold cake, never hot onto hot.","Resting the batter lets the semolina hydrate, which is the difference between tender and gritty."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_019','Greek Semolina and Olive Oil Cake','greek-semolina-olive-oil-cake','A syrup-soaked semolina cake with a coarse crumb, poured cold syrup over hot cake so it drinks rather than sogs.','semolina cake, revani, Greek dessert, suji cake');
