INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_020_1','rcp_world_020',1,'{"steps":["Rinse the lentils well and drain them thoroughly in a sieve.","Warm the oil and cook the onion slowly until soft and sweet.","Add garlic and bay leaves, stirring for one minute until fragrant.","Stir in the tomatoes and cook down for five minutes into a base.","Add the lentils and enough water to cover them by four centimetres.","Bring to the boil and skim the foam that rises in the first minutes.","Simmer covered for thirty-five minutes until the lentils are fully tender.","Crush a few lentils against the side of the pot to thicken the broth.","Season with salt, pepper and oregano now that cooking has finished.","Serve with vinegar and a further pour of raw oil at the table."],"blocks":[{"id":"blk_world_020_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Fakes is deliberately plain until the vinegar arrives. Without it the soup reads as heavy; with it the whole bowl sharpens.","Add the vinegar in the bowl, not the pot, so each person can set the level themselves."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_020','Greek Lentil Soup with Bay and Vinegar','greek-lentil-soup-fakes','Greek fakes, where a hard splash of vinegar at the table is not optional but structural.','fakes, Greek lentil soup, bay leaf, red wine vinegar');
