INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_021_1','rcp_world_021',1,'{"steps":["Toast the plain seeds in a dry pan until golden and fragrant throughout.","Keep the toasted seeds warm, because cold seeds seize the honey instantly.","Heat the honey, sugar, salt and lemon juice together in a heavy pan.","Bring to 150C on a thermometer, watching it closely near the end.","Tip in all the sesame seeds at once and stir fast to coat them.","Work quickly, because the mixture stiffens within about a minute.","Scrape onto parchment and lay a second sheet over the top.","Roll flat to about eight millimetres with firm, even pressure.","Score into bars while still warm, cutting through the top sheet.","Cool completely, then snap along the scored lines and store airtight."],"blocks":[{"id":"blk_world_021_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Pasteli is two ingredients cooked to a temperature. Undershoot and it stays tacky; overshoot and it shatters like glass.","Have the tray, parchment and rolling pin ready before you start. Once the honey reaches temperature you have about a minute."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_021','Greek Sesame Pasteli Bars','greek-sesame-pasteli-bars','Sesame and honey cooked to a precise stage and set thin, the oldest energy bar there is.','pasteli, sesame honey bar, Greek sweet, sesame seeds');
