INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_022_1','rcp_world_022',1,'{"steps":["Melt the butter and soften the onion without letting it take colour.","Add the grated tomato and cook until the liquid has mostly gone.","Stir the daliya through the base so every grain is coated in fat.","Pour in the hot stock steadily while stirring to prevent lumps forming.","Simmer for twenty minutes, stirring often as it thickens considerably.","Add more hot stock whenever it tightens past a pourable consistency.","Check the grain is tender rather than merely swollen before stopping.","Take the pot off the heat and let the bubbling subside completely.","Stir the crumbled cheese through so it melts into the residual heat.","Finish with a heavy grind of black pepper and serve immediately."],"blocks":[{"id":"blk_world_022_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Trahana thickens far more than looks likely while cooking, and then keeps thickening off the heat. Cook it looser than you want to eat it.","The cheese goes in off the heat. In a boiling pot it strings rather than melting into the soup."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_022','Greek Trahana-Style Cracked Wheat Soup','greek-trahana-daliya-soup','Cracked wheat simmered in stock until it thickens on its own, finished with cheese and a great deal of pepper.','trahana, cracked wheat soup, Greek soup, daliya');
