INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_023','World kitchen 023','Levantine Fattoush with Flax Crisps','levantine-fattoush-with-flax-crisps','The bread salad rebuilt with baked flax crisps, which stay crunchy far longer than fried pita.',20,15,4,'["vegetarian","vegan"]','published','rcv_world_023_1','2026-08-16T09:00:00Z','Levantine Fattoush with Flax Crisps — True Grit','The bread salad rebuilt with baked flax crisps, which stay crunchy far longer than fried pita.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','fattoush, sumac salad, flax crisps, Levantine',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Levantine Fattoush with Flax Crisps, made with True Grit staples',NULL,'Levantine');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_023_1','rcp_world_023',1,'{"steps":["Soak the flax seeds in the water for thirty minutes until thickly gelled.","Season the gel with salt and spread it very thinly on parchment.","Bake at 150C for forty minutes until completely dry and brittle.","Cool the sheet fully, then snap it into rough shard-sized pieces.","Chop the cucumber, tomato and radish into pieces of similar size.","Whisk the lemon juice, oil, sumac, salt and pepper into a dressing.","Combine the vegetables and herbs in a wide, shallow serving bowl.","Keep the flax shards separate until the moment you sit down to eat.","Pour over the dressing and toss the vegetables through it quickly.","Scatter the shards over the top and serve immediately while crisp."],"blocks":[{"id":"blk_world_023_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Fattoush usually goes soggy within minutes. Flax crisps hold their crunch much longer because they carry no absorbent crumb.","Dress at the table, not in the kitchen. Every minute the salad sits dressed costs it texture."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_023','Levantine Fattoush with Flax Crisps','levantine-fattoush-with-flax-crisps','The bread salad rebuilt with baked flax crisps, which stay crunchy far longer than fried pita.','fattoush, sumac salad, flax crisps, Levantine');
