INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_024','World kitchen 024','Turkish Sesame Halva Blocks','turkish-sesame-halva-blocks','Tahini and cooked sugar folded just enough to leave the flaky strands that define a good halva.',20,20,16,'["vegetarian","gluten free"]','published','rcv_world_024_1','2026-08-16T09:00:00Z','Turkish Sesame Halva Blocks — True Grit','Tahini and cooked sugar folded just enough to leave the flaky strands that define a good halva.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','sesame halva, tahini halva, Turkish sweet, helva',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Turkish Sesame Halva Blocks, made with True Grit staples',NULL,'Turkish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_024_1','rcp_world_024',1,'{"steps":["Warm the tahini gently in a bowl set over hot water until loose.","Stir the salt and vanilla through the warmed tahini and set it aside.","Heat the sugar, water and honey in a heavy pan without stirring it.","Bring the syrup to 120C, brushing down any crystals on the sides.","Pour the hot syrup into the warm tahini in a thin, steady stream.","Fold with a spatula only until the pale streaks have almost disappeared.","Stop deliberately early, because over-mixing destroys the flaky strands.","Fold the pistachios through with two or three strokes at most.","Press into a lined tin without compacting it more than necessary.","Cool, then refrigerate overnight before cutting into blocks."],"blocks":[{"id":"blk_world_024_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The flakiness comes from under-mixing. Fold the syrup into the tahini only until the streaks are nearly gone, then stop.","Keep stirring past that point and the strands break down into a uniform, heavy fudge instead."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_024','Turkish Sesame Halva Blocks','turkish-sesame-halva-blocks','Tahini and cooked sugar folded just enough to leave the flaky strands that define a good halva.','sesame halva, tahini halva, Turkish sweet, helva');
INSERT INTO recipe_ingredients (id,recipe_id,label,quantity_text,product_id,sort_order) VALUES ('rci_world_024_01','rcp_world_024','roasted sesame tahini','400 g',(SELECT id FROM products WHERE slug='roasted-sesame-seeds'),1);
