INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_025_1','rcp_world_025',1,'{"steps":["Soak the wheat grains in plenty of cold water overnight, then drain.","Boil them in fresh unsalted water for about an hour until tender.","Check for grains that have split open, which is the real doneness signal.","Drain and rinse immediately under cold water to stop the cooking.","Spread on a tray to dry a little so the dressing is not diluted.","Whisk the lemon juice and oil with plenty of salt and pepper.","Toss the cooled grains thoroughly in the dressing until every one glistens.","Fold in the herbs, spring onions and most of the pomegranate seeds.","Rest for thirty minutes so the grains take up the lemon and salt.","Scatter sesame and the remaining pomegranate over just before serving."],"blocks":[{"id":"blk_world_025_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Whole grains need far longer than any packet suggests, and they are ready only when several have visibly split open.","Rinse them under cold water the moment they are done, or residual heat keeps softening them into mush."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_025','Greek Wheat Berry Salad with Sesame','greek-wheat-berry-kolyva-salad','Whole emmer grains boiled until they burst, then dressed cold with sesame, herbs and pomegranate.','wheat berry salad, kolyva, Greek, whole wheat');
