INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_026','World kitchen 026','Sesame Chilli Salsa Macha','sesame-chilli-salsa-macha','A crunchy Mexican chilli oil where sesame seeds carry the texture and the oil never gets hot enough to scorch the chillies.',10,15,12,'["vegetarian","vegan","gluten free"]','published','rcv_world_026_1','2026-08-16T09:00:00Z','Sesame Chilli Salsa Macha — True Grit','A crunchy Mexican chilli oil where sesame seeds carry the texture and the oil never gets hot enough to scorch the chillies.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','salsa macha, chilli oil, Mexican condiment, sesame seeds',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/cold-pressed-oils.webp','Sesame Chilli Salsa Macha, made with True Grit staples',NULL,'Mexican');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_026_1','rcp_world_026',1,'{"steps":["Warm the oil over low heat until a single sesame seed sizzles lazily.","Fry the whole garlic cloves gently until pale gold, then lift them out.","Fry the nuts in the same oil for two minutes and remove them too.","Add the plain sesame seeds and stir constantly for barely one minute.","Turn off the heat completely before the chillies go near the pan.","Add the dried chillies to the hot oil off the heat and stir under.","Let them steep in the cooling oil for five minutes until softened.","Blend everything to a coarse rubble, keeping plenty of visible texture.","Stir in the salt, vinegar and roasted sesame seeds by hand.","Jar it with oil covering the solids and refrigerate for up to a month."],"blocks":[{"id":"blk_world_026_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Salsa macha is a chilli oil with things in it, and the only way to ruin it is heat. Scorched chilli turns the whole jar bitter with no recovery.","Keep the oil at the temperature where a seed sizzles lazily rather than dancing. If anything darkens quickly, pull the pan off the heat."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_026','Sesame Chilli Salsa Macha','sesame-chilli-salsa-macha','A crunchy Mexican chilli oil where sesame seeds carry the texture and the oil never gets hot enough to scorch the chillies.','salsa macha, chilli oil, Mexican condiment, sesame seeds');
