INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_027','World kitchen 027','Mexican Spiced Red Lentil Tostadas','mexican-red-lentil-tostadas','A mashed, spiced lentil topping that replaces refried beans without pretending to be them.',20,30,4,'["vegetarian","vegan"]','published','rcv_world_027_1','2026-08-16T09:00:00Z','Mexican Spiced Red Lentil Tostadas — True Grit','A mashed, spiced lentil topping that replaces refried beans without pretending to be them.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tostadas, lentil topping, Mexican, masoor',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Mexican Spiced Red Lentil Tostadas, made with True Grit staples',NULL,'Mexican');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_027_1','rcp_world_027',1,'{"steps":["Rinse the lentils and simmer them in plenty of water until fully soft.","Drain well, reserving a little of the cooking liquid separately.","Warm the oil and cook the onion until soft and lightly coloured.","Add garlic, cumin and smoked paprika, stirring one minute until fragrant.","Stir in the tomato paste and cook it briefly to lose the raw taste.","Add the drained lentils and mash them roughly in the pan.","Fry the mash for five minutes, stirring often, until it thickens further.","Loosen with the reserved liquid if it turns too stiff to spread.","Season with salt and a squeeze of lime just before serving.","Spread thickly on warm tostada shells and top with lettuce and salsa."],"blocks":[{"id":"blk_world_027_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["This is not a bean substitute pretending to be beans. Red lentils cook faster and mash smoother, and the spicing is built around that difference.","Fry the mashed lentils briefly at the end. It drives off excess moisture and the topping stops soaking through the tostada shell."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_027','Mexican Spiced Red Lentil Tostadas','mexican-red-lentil-tostadas','A mashed, spiced lentil topping that replaces refried beans without pretending to be them.','tostadas, lentil topping, Mexican, masoor');
