INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_028','World kitchen 028','Mexican Fideo Seco with Toasted Vermicelli','mexican-vermicelli-fideo-seco','Vermicelli toasted dark before it ever meets liquid, so the finished dish is dry, not soupy.',10,25,4,'["vegetarian","vegan"]','published','rcv_world_028_1','2026-08-16T09:00:00Z','Mexican Fideo Seco with Toasted Vermicelli — True Grit','Vermicelli toasted dark before it ever meets liquid, so the finished dish is dry, not soupy.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','fideo seco, toasted vermicelli, Mexican, dry noodle dish',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/whole-wheat-vermicelli.webp','Mexican Fideo Seco with Toasted Vermicelli, made with True Grit staples',NULL,'Mexican');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_028_1','rcp_world_028',1,'{"steps":["Blend the tomatoes, onion, garlic and softened dried chilli until smooth.","Warm the oil in a wide pan over medium heat until shimmering.","Add the vermicelli and toast it, stirring constantly, until deep golden brown.","Watch closely near the end, because the colour turns quickly at this stage.","Pour the blended sauce straight onto the hot toasted vermicelli carefully.","Let it sizzle and reduce for two minutes before adding any stock.","Add the hot stock, stir once, and bring back to a steady simmer.","Cover and cook for twelve minutes without stirring, so it stays intact.","Rest off the heat, covered, for five minutes to finish absorbing liquid.","Fluff gently with a fork and serve with coriander and lime."],"blocks":[{"id":"blk_world_028_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Fideo seco means dry noodle, and the whole method points there: toast the pasta hard first so it absorbs exactly the liquid it needs and no more.","Do not walk away during toasting. The strands go from pale to burnt in under a minute once they start colouring."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_028','Mexican Fideo Seco with Toasted Vermicelli','mexican-vermicelli-fideo-seco','Vermicelli toasted dark before it ever meets liquid, so the finished dish is dry, not soupy.','fideo seco, toasted vermicelli, Mexican, dry noodle dish');
