INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_029','World kitchen 029','Seeded Flaxseed Crackers','seeded-flaxseed-crackers','Whole flax seeds gel in water and bind themselves into a shatteringly crisp cracker with no flour at all.',15,60,8,'["vegetarian","vegan","gluten free"]','published','rcv_world_029_1','2026-08-16T09:00:00Z','Seeded Flaxseed Crackers — True Grit','Whole flax seeds gel in water and bind themselves into a shatteringly crisp cracker with no flour at all.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','flaxseed crackers, seed crackers, gluten free snack',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Seeded Flaxseed Crackers, made with True Grit staples',NULL,'American');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_029_1','rcp_world_029',1,'{"steps":["Stir all the seeds into the water with the salt and the oil.","Leave the mixture thirty minutes until it thickens into a spreadable gel.","Stir once more, because the seeds settle heavily towards the bottom.","Spread the mixture onto parchment as thinly and evenly as possible.","Aim for a single seed layer with no thick patches or bare holes.","Scatter pepper and chilli over the surface and press them in lightly.","Bake at 150C for thirty minutes until the surface is dry to the touch.","Score into squares, flip the whole sheet, and peel the parchment away.","Bake another twenty-five minutes until uniformly crisp with no flexible centre.","Cool completely on a rack and store airtight, re-crisping in a low oven if needed."],"blocks":[{"id":"blk_world_029_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["There is no flour and no binder here. Flax seeds release a gel in water that sets into a sheet as it dries, which is the entire trick.","Bake low and long. These do not brown so much as dehydrate, and any part still flexible when cool will be chewy rather than crisp."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_029','Seeded Flaxseed Crackers','seeded-flaxseed-crackers','Whole flax seeds gel in water and bind themselves into a shatteringly crisp cracker with no flour at all.','flaxseed crackers, seed crackers, gluten free snack');
