INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_030','World kitchen 030','American-Style Skillet Semolina Cornbread','american-cornbread-style-semolina-loaf','A part-semolina cornbread baked in a screaming hot skillet, which is what actually builds the crust.',10,25,8,'["vegetarian"]','published','rcv_world_030_1','2026-08-16T09:00:00Z','American-Style Skillet Semolina Cornbread — True Grit','A part-semolina cornbread baked in a screaming hot skillet, which is what actually builds the crust.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','cornbread, semolina bread, skillet bread, American',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/semolina.webp','American-Style Skillet Semolina Cornbread, made with True Grit staples',NULL,'American');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_030_1','rcp_world_030',1,'{"steps":["Put a cast iron skillet in the oven and heat it to 220C empty.","Whisk the cornmeal, semolina, baking powder and salt together.","Whisk the buttermilk, eggs, oil and honey together in a separate bowl.","Pour the wet mixture into the dry and stir only until just combined.","Do not overmix, or the crumb turns tough rather than tender.","Carefully remove the screaming hot skillet and add a little oil to it.","Swirl the oil to coat the sides, which is what forms the crust.","Pour the batter in immediately; it should sizzle audibly on contact.","Bake for twenty to twenty-five minutes until the top springs back.","Rest five minutes in the skillet, then turn out and slice while warm."],"blocks":[{"id":"blk_world_030_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The skillet has to be properly hot before batter goes anywhere near it. A cold pan gives a pale, cakey bottom instead of a crisp crust.","Semolina alongside the cornmeal adds a coarser bite than an all-cornmeal loaf, closer to a proper crumb than a cake."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_030','American-Style Skillet Semolina Cornbread','american-cornbread-style-semolina-loaf','A part-semolina cornbread baked in a screaming hot skillet, which is what actually builds the crust.','cornbread, semolina bread, skillet bread, American');
