INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_031_1','rcp_world_031',1,'{"steps":["Drain the soaked field peas and rinse well under running cold water.","Warm the oil and cook the onion slowly until soft and sweet.","Add the ground spices and stir a minute so they toast without burning.","Tip in the tomatoes and cook until they break down into a thick base.","Add the field peas and water, then bring the pot to a steady boil.","Simmer covered for fifty minutes until the peas are tender throughout.","Stir in the red lentils and cook a further twenty minutes uncovered.","Check the consistency and add hot water if it thickens too far.","Season with salt and pepper now the pulses have finished absorbing liquid.","Stir most of the herbs through and scatter the rest over each bowl."],"blocks":[{"id":"blk_world_031_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Two pulses doing two jobs: the field peas stay whole and give something to chew, the red lentils break down and thicken everything around them.","Soak the field peas overnight. Skipping it does not simply lengthen cooking, it produces peas unevenly hard in the same pot."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_031','Moroccan Field Pea and Lentil Stew','moroccan-field-pea-lentil-stew','White field peas hold their shape while red lentils dissolve into the broth, giving one pot two textures.','Moroccan stew, field peas, red lentils, harira style');
