INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_032','World kitchen 032','Moroccan Sesame Almond Filling for Pastries','moroccan-sesame-almond-briouat-filling','A fragrant almond and sesame paste, the filling that makes triangular Moroccan pastries worth the folding.',20,10,10,'["vegetarian","vegan"]','published','rcv_world_032_1','2026-08-16T09:00:00Z','Moroccan Sesame Almond Filling for Pastries — True Grit','A fragrant almond and sesame paste, the filling that makes triangular Moroccan pastries worth the folding.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','briouat filling, sesame almond, Moroccan pastry filling',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Moroccan Sesame Almond Filling for Pastries, made with True Grit staples',NULL,'Moroccan');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_032_1','rcp_world_032',1,'{"steps":["Toast the almonds in a dry pan until fragrant and lightly coloured.","Cool them fully, because warm nuts turn to paste too fast when ground.","Pulse the almonds in short bursts until coarsely and evenly ground.","Stop before they release oil and clump into a wet mass.","Grind the roasted sesame separately to a similarly coarse texture.","Combine the ground almonds, sesame, icing sugar, cinnamon and salt.","Work in the softened butter and orange blossom water by hand.","Add honey a teaspoon at a time only if the mixture will not hold together.","Roll into small balls, or reserve as a spoonable paste for pastries.","Store airtight; it keeps a week at room temperature or a month chilled."],"blocks":[{"id":"blk_world_032_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["This filling stands alone as a spoonable sweet, or fills briouat pastry if you want to fold and fry it. Both are worth doing.","Grind the almonds coarsely rather than to a powder. A little bite in the paste is what separates it from marzipan."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_032','Moroccan Sesame Almond Filling for Pastries','moroccan-sesame-almond-briouat-filling','A fragrant almond and sesame paste, the filling that makes triangular Moroccan pastries worth the folding.','briouat filling, sesame almond, Moroccan pastry filling');
