INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_033','World kitchen 033','Moroccan-Style Cracked Wheat with Seven Vegetables','moroccan-daliya-couscous-style','The classic seven-vegetable stew served over steamed daliya instead of couscous, staggered so nothing overcooks.',25,60,6,'["vegetarian","vegan","gluten free"]','published','rcv_world_033_1','2026-08-16T09:00:00Z','Moroccan-Style Cracked Wheat with Seven Vegetables — True Grit','The classic seven-vegetable stew served over steamed daliya instead of couscous, staggered so nothing overcooks.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','cracked wheat, seven vegetable stew, Moroccan, daliya',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Moroccan-Style Cracked Wheat with Seven Vegetables, made with True Grit staples',NULL,'Moroccan');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_033_1','rcp_world_033',1,'{"steps":["Simmer the soaked chickpeas in unsalted water until nearly tender.","Warm the oil and cook the onion with the ground spices until fragrant.","Add the carrots and turnips first, since they take the longest to soften.","Pour in the stock, bring to the boil, then simmer twenty minutes.","Add the chickpeas and the pumpkin, which need a medium cooking time.","Simmer fifteen further minutes before the courgette goes in last.","Cook the courgette gently for ten minutes so it holds some shape.","Meanwhile steam the daliya over simmering water for twenty-five minutes.","Fluff the steamed daliya with a fork and season it lightly with salt.","Spoon the vegetables and broth generously over the grain to serve."],"blocks":[{"id":"blk_world_033_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The vegetables go in staggered by how long each takes, which is the part most home versions skip. A carrot and a courgette do not need the same time.","Steam the daliya rather than boiling it. Boiled grain turns gluey; steamed grain stays separate and takes seasoning better."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_033','Moroccan-Style Cracked Wheat with Seven Vegetables','moroccan-daliya-couscous-style','The classic seven-vegetable stew served over steamed daliya instead of couscous, staggered so nothing overcooks.','cracked wheat, seven vegetable stew, Moroccan, daliya');
