INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_034','World kitchen 034','Ethiopian Misir Wot Red Lentil Stew','ethiopian-lentil-misir-wot','A deep red, chilli-forward lentil stew built on a long-cooked onion base, the way Ethiopian cooking usually starts.',15,45,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_034_1','2026-08-16T09:00:00Z','Ethiopian Misir Wot Red Lentil Stew — True Grit','A deep red, chilli-forward lentil stew built on a long-cooked onion base, the way Ethiopian cooking usually starts.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','misir wot, Ethiopian lentil stew, berbere, red lentils',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Ethiopian Misir Wot Red Lentil Stew, made with True Grit staples',NULL,'Ethiopian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_034_1','rcp_world_034',1,'{"steps":["Cook the chopped onions in a dry pot over medium heat, stirring often.","Continue until they soften and release their own liquid, about ten minutes.","Add the oil once the onions are collapsing, not before.","Stir in the garlic and ginger and cook two minutes until fragrant.","Add the berbere and tomato paste, stirring constantly for one minute.","Pour in the water and bring the pot to a steady simmer.","Rinse the lentils and add them, stirring to distribute the spice evenly.","Simmer uncovered for thirty minutes, stirring occasionally as it thickens.","Add more water if it thickens past a spoonable consistency too soon.","Season with salt only at the end and rest five minutes before serving."],"blocks":[{"id":"blk_world_034_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The onions are cooked dry first, without oil, until they release their own moisture and soften. Oil goes in only once they are already collapsing.","Berbere burns fast in hot fat, the same as any ground chilli spice blend, so bloom it briefly and keep the heat moderate."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_034','Ethiopian Misir Wot Red Lentil Stew','ethiopian-lentil-misir-wot','A deep red, chilli-forward lentil stew built on a long-cooked onion base, the way Ethiopian cooking usually starts.','misir wot, Ethiopian lentil stew, berbere, red lentils');
