INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_035','World kitchen 035','Ethiopian-Inspired Fermented Daliya Flatbread','ethiopian-injera-style-daliya-flatbread','A three-day fermented batter using ground daliya in place of teff, spongy enough to scoop stew with.',15,20,6,'["vegetarian","vegan"]','published','rcv_world_035_1','2026-08-16T09:00:00Z','Ethiopian-Inspired Fermented Daliya Flatbread — True Grit','A three-day fermented batter using ground daliya in place of teff, spongy enough to scoop stew with.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','injera style, fermented flatbread, daliya, Ethiopian',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Ethiopian-Inspired Fermented Daliya Flatbread, made with True Grit staples',NULL,'Ethiopian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_035_1','rcp_world_035',1,'{"steps":["Blend the daliya with the water until smooth and pourable, then strain.","Stir the yoghurt into the batter to introduce a starter culture.","Cover loosely and leave at room temperature for three days.","Stir once daily and watch for small bubbles forming across the surface.","On the day of cooking, stir in the salt and thin with a little water.","Heat a wide non-stick pan over medium heat with a trace of oil.","Pour a thin layer of batter in a spiral from the outside in.","Cover and cook without flipping until the surface is fully set and pitted.","The underside should be lightly golden with no raw batter remaining.","Slide onto a cloth to cool flat and repeat with the rest of the batter."],"blocks":[{"id":"blk_world_035_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["This borrows injera''s fermentation and spongy texture without claiming to be the real thing, which is properly made with teff.","The batter needs three days at room temperature to sour. Do not rush it in the fridge; cold slows the fermentation almost to a stop."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_035','Ethiopian-Inspired Fermented Daliya Flatbread','ethiopian-injera-style-daliya-flatbread','A three-day fermented batter using ground daliya in place of teff, spongy enough to scoop stew with.','injera style, fermented flatbread, daliya, Ethiopian');
