INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_036','World kitchen 036','Gomashio and Everyday Sesame Dressing','gomashio-sesame-dressing','One pan of toasted sesame becomes two things: a crunchy sesame salt for the table, and a pourable dressing for greens.',15,5,16,'["vegetarian","vegan","gluten free"]','published','rcv_world_036_1','2026-08-16T09:00:00Z','Gomashio and Everyday Sesame Dressing — True Grit','One pan of toasted sesame becomes two things: a crunchy sesame salt for the table, and a pourable dressing for greens.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','gomashio, sesame salt, Japanese dressing, sesame seeds',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Gomashio and Everyday Sesame Dressing, made with True Grit staples',NULL,'Japanese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_036_1','rcp_world_036',1,'{"steps":["Toast the plain seeds in a dry pan over medium heat, shaking constantly.","Stop the moment they smell nutty and a few seeds pop and jump.","Tip them straight out of the hot pan so they cannot keep cooking.","Toast the salt separately for a minute to drive off residual moisture.","Grind salt and seeds together lightly until roughly half are cracked.","Stop well before a paste forms, then cool and store in a jar.","For the dressing, grind the roasted seeds to a coarse, oily rubble.","Whisk in the vinegar, soy and honey before adding any of the oil.","Add the sesame oil in a thin stream, whisking until it thickens slightly.","Use the gomashio within a month and the dressing within a week, chilled."],"blocks":[{"id":"blk_world_036_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Gomashio is sesame and salt ground just enough to release the oil, and no further. Grind it to a paste and you have made tahini by accident.","The ratio matters more than the technique. Around fifteen parts sesame to one part salt keeps it a seasoning rather than a salt cellar."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_036','Gomashio and Everyday Sesame Dressing','gomashio-sesame-dressing','One pan of toasted sesame becomes two things: a crunchy sesame salt for the table, and a pourable dressing for greens.','gomashio, sesame salt, Japanese dressing, sesame seeds');
