INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_037','World kitchen 037','Japanese Sesame Spinach Ohitashi','japanese-sesame-spinach-ohitashi','Blanched spinach shocked in ice water and coated in a thick sesame sauce, a side dish built on one small detail: squeezing dry.',10,5,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_037_1','2026-08-16T09:00:00Z','Japanese Sesame Spinach Ohitashi — True Grit','Blanched spinach shocked in ice water and coated in a thick sesame sauce, a side dish built on one small detail: squeezing dry.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','goma-ae, ohitashi, sesame spinach, Japanese side dish',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Japanese Sesame Spinach Ohitashi, made with True Grit staples',NULL,'Japanese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_037_1','rcp_world_037',1,'{"steps":["Bring a large pot of water to a rolling boil and salt it.","Prepare a bowl of ice water alongside the stove before you start.","Blanch the spinach for exactly thirty seconds, no longer.","Lift it straight into the ice water to stop the cooking sharply.","Once fully cold, squeeze the spinach hard in your fists to remove water.","Squeeze again from a different angle, because a first pass never gets it all.","Grind most of the sesame seeds to a coarse, oily paste in a mortar.","Mix in the soy sauce, sugar, mirin and sesame oil until smooth.","Cut the squeezed spinach into short lengths and toss with the sauce.","Scatter the remaining whole seeds over the top and serve at room temperature."],"blocks":[{"id":"blk_world_037_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The whole dish hinges on squeezing the spinach properly dry after blanching. Wet spinach dilutes the sauce and the dish turns watery on the plate.","Blanch briefly and shock immediately in ice water. That stops the cooking and is what keeps the green colour vivid rather than dull."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_037','Japanese Sesame Spinach Ohitashi','japanese-sesame-spinach-ohitashi','Blanched spinach shocked in ice water and coated in a thick sesame sauce, a side dish built on one small detail: squeezing dry.','goma-ae, ohitashi, sesame spinach, Japanese side dish');
