INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_038','World kitchen 038','Japanese Goma Dofu Sesame Tofu','japanese-goma-dofu-sesame-tofu','No soy in this tofu at all: sesame paste, starch and water, whisked constantly until it sets into a wobbling custard.',15,20,6,'["vegetarian","vegan","gluten free"]','published','rcv_world_038_1','2026-08-16T09:00:00Z','Japanese Goma Dofu Sesame Tofu — True Grit','No soy in this tofu at all: sesame paste, starch and water, whisked constantly until it sets into a wobbling custard.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','goma dofu, sesame tofu, Japanese, kudzu starch',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Japanese Goma Dofu Sesame Tofu, made with True Grit staples',NULL,'Japanese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_038_1','rcp_world_038',1,'{"steps":["Dissolve the starch completely in a small amount of the cold water.","Whisk the sesame paste with the remaining water until fully smooth.","Combine both mixtures with the salt in a heavy-bottomed pan.","Set over low heat and begin whisking continuously without any pause.","Keep whisking as it slowly thickens, which takes a good ten minutes.","Switch to a spatula once it becomes too thick to whisk easily.","Continue stirring hard until it turns glossy, heavy and fully translucent.","Pour immediately into wet moulds or bowls before it starts to set.","Smooth the tops quickly, because it firms within a couple of minutes.","Chill for at least two hours, then unmould and serve with soy and wasabi."],"blocks":[{"id":"blk_world_038_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Goma dofu contains no soy whatsoever. It is sesame paste thickened with starch, and the name refers to its texture rather than its ingredients.","You must whisk without stopping once it hits the heat. A moment''s pause and the starch clumps into lumps that will not smooth out again."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_038','Japanese Goma Dofu Sesame Tofu','japanese-goma-dofu-sesame-tofu','No soy in this tofu at all: sesame paste, starch and water, whisked constantly until it sets into a wobbling custard.','goma dofu, sesame tofu, Japanese, kudzu starch');
