INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_039','World kitchen 039','Korean Sesame Oil Japchae with Vermicelli','korean-sesame-oil-japchae','Wheat vermicelli standing in for sweet potato glass noodles, with each vegetable stir-fried separately so nothing turns grey.',25,20,4,'["vegetarian","vegan"]','published','rcv_world_039_1','2026-08-16T09:00:00Z','Korean Sesame Oil Japchae with Vermicelli — True Grit','Wheat vermicelli standing in for sweet potato glass noodles, with each vegetable stir-fried separately so nothing turns grey.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','japchae, glass noodles, sesame oil, Korean, vermicelli',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/whole-wheat-vermicelli.webp','Korean Sesame Oil Japchae with Vermicelli, made with True Grit staples',NULL,'Korean');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_039_1','rcp_world_039',1,'{"steps":["Boil the vermicelli until just tender, then drain and toss with sesame oil.","Snip the noodles a few times with scissors so they are easier to eat.","Blanch the spinach briefly, shock in cold water and squeeze dry.","Stir-fry the carrot alone in a hot pan for two minutes and set aside.","Stir-fry the onion and mushrooms together until softened, then set aside.","Toss the noodles with half the soy sauce and sugar in the empty pan.","Cook briefly over medium heat until the noodles turn glossy and darker.","Return all the vegetables to the pan and toss everything together.","Add the remaining soy sauce and sugar, tasting and adjusting the balance.","Finish with a drizzle of sesame oil and the roasted sesame seeds."],"blocks":[{"id":"blk_world_039_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Japchae is built from components cooked separately and combined at the end. Throwing everything into one pan at once is what makes home versions turn to mush.","Season the noodles themselves, not just the vegetables. A noodle dish where only the toppings taste of anything is a common and avoidable mistake."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_039','Korean Sesame Oil Japchae with Vermicelli','korean-sesame-oil-japchae','Wheat vermicelli standing in for sweet potato glass noodles, with each vegetable stir-fried separately so nothing turns grey.','japchae, glass noodles, sesame oil, Korean, vermicelli');
