INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_040','World kitchen 040','Korean Sesame Lettuce Wraps with Field Peas','korean-sesame-lettuce-wraps','Braised field peas in a sweet-savoury glaze, wrapped in lettuce with rice and a spoon of sesame sauce.',15,20,4,'["vegetarian","vegan"]','published','rcv_world_040_1','2026-08-16T09:00:00Z','Korean Sesame Lettuce Wraps with Field Peas — True Grit','Braised field peas in a sweet-savoury glaze, wrapped in lettuce with rice and a spoon of sesame sauce.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','ssam, lettuce wraps, Korean, field peas, sesame',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/white-field-peas.webp','Korean Sesame Lettuce Wraps with Field Peas, made with True Grit staples',NULL,'Korean');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_040_1','rcp_world_040',1,'{"steps":["Cook the soaked field peas in fresh water until fully tender, then drain.","Warm a spoonful of sesame oil and cook the garlic and ginger briefly.","Add the peas, soy sauce and brown sugar, stirring to coat evenly.","Simmer, stirring often, until the liquid reduces to a sticky glaze.","Watch closely in the last few minutes so the sugar does not catch.","Stir the remaining sesame oil through the glazed peas off the heat.","Wash and dry the lettuce leaves and arrange them on a large platter.","Fluff the rice and place a small bowl of it alongside the leaves.","Scatter roasted sesame seeds over the glazed peas before serving.","Let everyone spoon rice and peas into a leaf and wrap it themselves."],"blocks":[{"id":"blk_world_040_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Ssam is assembly, not cooking. Everything on the plate is ready before anyone sits down, and diners build their own wraps at the table.","The glaze needs to reduce until it coats rather than pools. A watery glaze runs straight out of the lettuce leaf and down your arm."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_040','Korean Sesame Lettuce Wraps with Field Peas','korean-sesame-lettuce-wraps','Braised field peas in a sweet-savoury glaze, wrapped in lettuce with rice and a spoon of sesame sauce.','ssam, lettuce wraps, Korean, field peas, sesame');
