INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_041_1','rcp_world_041',1,'{"steps":["Boil the noodles according to the packet until just tender.","Drain immediately and rinse thoroughly under cold running water.","Toss with a teaspoon of sesame oil to stop them sticking together.","Whisk the sesame paste with two tablespoons of hot water first.","Keep whisking until it loosens into a smooth, pourable sauce.","Add the soy sauce, vinegar, sugar, garlic and remaining sesame oil.","Whisk until fully combined and taste for the sweet-salty-sour balance.","Add more hot water, a teaspoon at a time, if it feels too thick.","Toss the cold noodles thoroughly in the sauce until every strand is coated.","Top with cucumber, spring onion and chilli oil, and serve chilled."],"blocks":[{"id":"blk_world_041_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Sesame paste is dense and will not coat noodles evenly straight from the jar. Thin it with hot water before it ever meets the noodles.","Rinse the noodles in cold water the moment they are cooked. Skip that step and residual heat turns them into a single starchy clump."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_041','Chinese Cold Sesame Noodles','chinese-sesame-noodles-cold','Chilled noodles in a thick sesame and soy sauce, correct only when the sauce is loosened with enough hot water first.','cold sesame noodles, Chinese, sesame paste, vermicelli');
