INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_042','World kitchen 042','Chinese-Style Red Lentil and Rice Congee','chinese-lentil-congee','A slow rice porridge with red lentils folded in for body, cooked low enough that it thickens without ever catching.',10,60,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_042_1','2026-08-16T09:00:00Z','Chinese-Style Red Lentil and Rice Congee — True Grit','A slow rice porridge with red lentils folded in for body, cooked low enough that it thickens without ever catching.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','congee, rice porridge, red lentils, Chinese breakfast',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Chinese-Style Red Lentil and Rice Congee, made with True Grit staples',NULL,'Chinese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_042_1','rcp_world_042',1,'{"steps":["Combine the rice, lentils, water and ginger in a heavy pot.","Bring to the boil, then drop immediately to the lowest possible simmer.","Leave it barely bubbling, uncovered, stirring only every ten minutes or so.","Cook for around fifty minutes, until the grains have mostly collapsed.","Add more hot water along the way if it thickens past pourable.","Taste periodically and note how much the texture changes as it cooks.","Stir in the sesame oil once the congee has reached the texture you want.","Season with salt and white pepper, tasting again after each addition.","Simmer five more minutes to let the seasoning settle through the pot.","Ladle into bowls and top with spring onion and roasted sesame seeds."],"blocks":[{"id":"blk_world_042_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Congee wants a very low, very long simmer. Rushing it with high heat gives you rice soup, not the silky, collapsed texture congee is meant to have.","Stir occasionally rather than constantly. Too much stirring breaks the grains down unevenly and the texture turns pasty instead of smooth."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_042','Chinese-Style Red Lentil and Rice Congee','chinese-lentil-congee','A slow rice porridge with red lentils folded in for body, cooked low enough that it thickens without ever catching.','congee, rice porridge, red lentils, Chinese breakfast');
