INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_043_1','rcp_world_043',1,'{"steps":["Boil the vermicelli briefly until just tender, then drain and rinse cold.","Toss with the sesame oil to keep the strands from sticking together.","Whisk the lime juice, fish sauce, sugar, garlic and chilli together.","Taste and adjust: more lime for sharpness, more sugar to round it out.","Julienne the carrot and cucumber into fine, even matchsticks.","Pick the herb leaves from their stems and keep them whole where possible.","Divide the noodles between bowls and top with the vegetables and herbs.","Scatter crushed peanuts generously over each finished portion.","Pour the dressing over just before eating, not before serving.","Toss everything together at the table so the noodles stay loose."],"blocks":[{"id":"blk_world_043_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Everything here is built to be assembled cold and fast: cook the noodles, prepare the vegetables, make the dressing, and combine only when serving.","Balance the dressing by taste, not by exact measure. Lime, sugar and fish sauce vary enough by brand that a fixed ratio rarely lands right first time."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_043','Vietnamese Vermicelli Noodle Salad','vietnamese-vermicelli-noodle-salad','A wheat vermicelli bun-style bowl, where the dressing is made separately and only meets the noodles at the table.','bun style salad, vermicelli salad, Vietnamese, nuoc cham');
