INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_044_1','rcp_world_044',1,'{"steps":["Open the coconut milk gently and spoon off the thick cream on top.","Warm the oil and the coconut cream together in a wide pan.","Add the curry paste and fry until the oil separates and it smells fragrant.","Rinse the lentils and stir them into the fried paste to coat.","Add the remaining coconut milk, the water and the torn lime leaves.","Bring to a simmer and cook uncovered for twenty minutes.","Stir occasionally, since red lentils settle and can catch on the base.","Add more water if it thickens past a spoonable consistency too fast.","Season with fish sauce and sugar, tasting for the sweet-salty balance.","Finish with coriander and a squeeze of lime just before serving."],"blocks":[{"id":"blk_world_044_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["A tin of coconut milk separates into thick cream on top and thinner liquid below. Fry the curry paste in that cream first; it is where the fat is.","Do not shake the tin before opening it. Separation is what you want here, not something to mix away."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
