INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_045_1','rcp_world_045',1,'{"steps":["Slice the cucumbers thinly and toss them with the salt in a colander.","Leave to drain over the sink for twenty minutes, until visibly weeping.","Press gently and pat the slices dry with a clean cloth.","Toast the sesame seeds in a dry pan until golden and fragrant.","Whisk the vinegar and sugar until the sugar has fully dissolved.","Stir in the sesame oil so the dressing turns lightly glossy.","Toss the drained cucumber with the dressing in a wide bowl.","Add the sliced chilli and toss again to distribute it evenly.","Rest for five minutes so the cucumber takes up the dressing.","Scatter the toasted sesame and coriander over just before serving."],"blocks":[{"id":"blk_world_045_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Salting and draining the cucumber first is not optional. Skip it and the dressing pools in a watery puddle at the bottom of the bowl.","Toast the sesame seeds fresh rather than using them straight from the packet. Pre-toasted seeds that have sat around lose their aroma quickly."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_045','Thai Sesame Cucumber Salad','thai-sesame-cucumber-salad','Salted, drained cucumber tossed in a sharp sesame dressing, the salting step being the one nobody wants to bother with and shouldn''t skip.','cucumber salad, Thai, sesame, quick pickle');
