INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_046','World kitchen 046','Japanese Sesame Miso Daliya Donburi','japanese-sesame-miso-daliya-donburi','A rice-bowl-style dish where steamed daliya replaces rice, glazed in a sesame miso sauce that reduces to a lacquer.',15,25,3,'["vegetarian"]','published','rcv_world_046_1','2026-08-16T09:00:00Z','Japanese Sesame Miso Daliya Donburi — True Grit','A rice-bowl-style dish where steamed daliya replaces rice, glazed in a sesame miso sauce that reduces to a lacquer.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','donburi, miso, sesame, daliya bowl, Japanese rice bowl',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Japanese Sesame Miso Daliya Donburi, made with True Grit staples',NULL,'Japanese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_046_1','rcp_world_046',1,'{"steps":["Rinse the daliya and steam it over simmering water for twenty-five minutes.","Check it is tender with a little bite, then keep it warm covered.","Whisk the miso, tahini, mirin and soy sauce together until smooth.","Warm the sesame oil in a small pan over low heat only.","Add the miso mixture and stir gently, never letting it reach a boil.","Cook for two minutes until it thickens slightly and turns glossy.","Taste and adjust with a touch more mirin if it tastes too salty.","Fluff the steamed daliya into bowls as the base of each portion.","Spoon the warm miso glaze generously over the daliya.","Top with the steamed vegetable, spring onion and sesame seeds."],"blocks":[{"id":"blk_world_046_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Miso should never boil hard once it is in the pan. High heat kills its fermented character and leaves the sauce tasting flat and salty instead.","The daliya is steamed separately so it keeps its own texture rather than absorbing the sauce and turning soft throughout."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_046','Japanese Sesame Miso Daliya Donburi','japanese-sesame-miso-daliya-donburi','A rice-bowl-style dish where steamed daliya replaces rice, glazed in a sesame miso sauce that reduces to a lacquer.','donburi, miso, sesame, daliya bowl, Japanese rice bowl');
