INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_047','World kitchen 047','Korean Sesame Daliya Bibimbap','korean-sesame-daliya-bibimbap','Steamed daliya under a fan of separately seasoned vegetables, finished with gochujang and a crisped fried egg.',30,25,4,'["vegetarian"]','published','rcv_world_047_1','2026-08-16T09:00:00Z','Korean Sesame Daliya Bibimbap — True Grit','Steamed daliya under a fan of separately seasoned vegetables, finished with gochujang and a crisped fried egg.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','bibimbap, daliya, gochujang, sesame, Korean rice bowl',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Korean Sesame Daliya Bibimbap, made with True Grit staples',NULL,'Korean');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_047_1','rcp_world_047',1,'{"steps":["Steam the daliya over simmering water for twenty-five minutes until tender.","Blanch the spinach and bean sprouts separately, then squeeze both dry.","Season each with a little sesame oil and salt in its own small bowl.","Stir-fry the carrot alone for two minutes and season it the same way.","Stir-fry the mushrooms in a dry pan until they release their liquid.","Season the mushrooms with a splash of sesame oil once they are done.","Fry the eggs last, in a hot well-oiled pan, until the edges crisp.","Divide the warm daliya between four wide bowls as the base.","Arrange each vegetable in its own section around the bowl, egg on top.","Serve with gochujang and sesame seeds for each person to stir through."],"blocks":[{"id":"blk_world_047_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Each vegetable is seasoned in the pan it was cooked in, not later in a bowl. That is what gives bibimbap its layered rather than mixed flavour before stirring.","The egg wants a crisp lacy edge and a runny yolk. Cook it last, in the hottest pan, so it does not sit and overcook while everything else is arranged."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_047','Korean Sesame Daliya Bibimbap','korean-sesame-daliya-bibimbap','Steamed daliya under a fan of separately seasoned vegetables, finished with gochujang and a crisped fried egg.','bibimbap, daliya, gochujang, sesame, Korean rice bowl');
