INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_048_1','rcp_world_048',1,'{"steps":["Cook the soaked field peas in fresh water until tender, then drain well.","Pat the cooked peas dry so they do not spit when they hit hot oil.","Heat the wok until faintly smoking before any oil goes in.","Add the neutral oil, then the garlic and ginger, stirring constantly.","Cook for thirty seconds only, until fragrant but not browned.","Add the peas and toss hard over high heat for two minutes.","Splash in the wine along the side of the wok so it sizzles.","Add the soy sauce and toss until everything is glossy and coated.","Take the wok off the heat before the spring onions go in.","Stir through the sesame oil, sesame seeds and spring onions, then serve."],"blocks":[{"id":"blk_world_048_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Sesame oil is a finishing oil here, not a cooking one. Added to a screaming hot wok it turns bitter, so it goes in only once the heat is off.","Cook the peas ahead so the stir-fry itself is fast. A wok dish that lingers on the heat stops being a stir-fry and starts being a braise."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_048','Chinese Sesame Oil White Pea Stir-Fry','chinese-sesame-oil-pulse-stir-fry','Pre-cooked white field peas stir-fried hard and fast, finished with sesame oil off the heat so the aroma survives.','stir-fry, white peas, sesame oil, Chinese, wok cooking');
