INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_049','World kitchen 049','Vietnamese Daliya and Herb Spring Rolls','vietnamese-daliya-fresh-spring-rolls','Rice paper rolls filled with seasoned daliya and a wall of raw herbs, dipped in a sesame-thickened peanut sauce.',35,15,4,'["vegetarian","vegan"]','published','rcv_world_049_1','2026-08-16T09:00:00Z','Vietnamese Daliya and Herb Spring Rolls — True Grit','Rice paper rolls filled with seasoned daliya and a wall of raw herbs, dipped in a sesame-thickened peanut sauce.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','fresh spring rolls, goi cuon, daliya, rice paper',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Vietnamese Daliya and Herb Spring Rolls, made with True Grit staples',NULL,'Vietnamese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_049_1','rcp_world_049',1,'{"steps":["Cook the daliya in salted water until tender, drain, and cool completely.","Season the cooled daliya lightly with a splash of soy sauce.","Set out the daliya, carrot, herbs and lettuce in separate small piles.","Fill a wide shallow dish with warm water for softening the wrappers.","Dip one rice paper sheet for a few seconds until just pliable.","Lay it flat and place lettuce, daliya, carrot and herbs across the centre.","Fold the sides in firmly, then roll from the bottom, tucking as you go.","Keep finished rolls under a damp cloth so they do not dry out.","Whisk the peanut butter and tahini with soy sauce, lime and hot water.","Adjust the dip with more hot water until it pours easily, then serve."],"blocks":[{"id":"blk_world_049_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Soak the rice paper for only a few seconds. It keeps softening after it leaves the water, and oversoaked paper tears the moment you try to roll it.","Pack the herbs generously and near the outer edge. They are what shows through the wrapper and what most of the flavour comes from."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_049','Vietnamese Daliya and Herb Spring Rolls','vietnamese-daliya-fresh-spring-rolls','Rice paper rolls filled with seasoned daliya and a wall of raw herbs, dipped in a sesame-thickened peanut sauce.','fresh spring rolls, goi cuon, daliya, rice paper');
