INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_050','World kitchen 050','Nordic Emmer and Flax Breakfast Porridge','nordic-emmer-flax-porridge','Paigambari daliya simmered slowly with milk and finished with roasted flax, closer to a Nordic grot than a sweet kheer.',5,25,2,'["vegetarian"]','published','rcv_world_050_1','2026-08-16T09:00:00Z','Nordic Emmer and Flax Breakfast Porridge — True Grit','Paigambari daliya simmered slowly with milk and finished with roasted flax, closer to a Nordic grot than a sweet kheer.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','emmer porridge, flax breakfast, Scandinavian, daliya',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Nordic Emmer and Flax Breakfast Porridge, made with True Grit staples',NULL,'Scandinavian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_050_1','rcp_world_050',1,'{"steps":["Rinse the daliya briefly and drain so the porridge does not turn cloudy.","Bring the water to the boil and stir the daliya in steadily.","Simmer ten minutes until the grain has taken up nearly all the water.","Pour in the milk gradually, stirring so the porridge stays smooth.","Cook very gently for fifteen minutes, stirring often to stop it catching.","Add the salt once the grain is soft, and taste before adding more.","Loosen with a splash of hot milk if it has thickened past what you want.","Rest the pan covered off the heat for five minutes before serving.","Spoon into bowls and press a knob of butter into the centre of each.","Scatter the roasted flax and cinnamon over the top and drizzle with honey."],"blocks":[{"id":"blk_world_050_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["A Nordic breakfast porridge is barely sweet and heavily salted by Indian standards. The salt is what makes the grain taste of itself.","Add the flax at the very end. Roasted flax loses its character in a long simmer, and ground flax turns the porridge gluey."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_050','Nordic Emmer and Flax Breakfast Porridge','nordic-emmer-flax-porridge','Paigambari daliya simmered slowly with milk and finished with roasted flax, closer to a Nordic grot than a sweet kheer.','emmer porridge, flax breakfast, Scandinavian, daliya');
