INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_051','World kitchen 051','Swedish-Style Sesame Crispbread','swedish-rye-style-sesame-crispbread','A thin, docked flatbread baked until it snaps clean, the kind that is meant to keep for weeks in a tin.',20,20,12,'["vegetarian","vegan"]','published','rcv_world_051_1','2026-08-16T09:00:00Z','Swedish-Style Sesame Crispbread — True Grit','A thin, docked flatbread baked until it snaps clean, the kind that is meant to keep for weeks in a tin.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','crispbread, knackebrod, sesame, Swedish, wheat flour',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/wheat-flour.webp','Swedish-Style Sesame Crispbread, made with True Grit staples',NULL,'Swedish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_051_1','rcp_world_051',1,'{"steps":["Mix the flour, plain sesame seeds, salt and baking powder in a bowl.","Add the water and oil, bringing it together into a firm, dry dough.","Knead briefly just until smooth, then rest it for fifteen minutes.","Divide into four pieces and roll each as thin as possible on parchment.","Scatter roasted sesame seeds over the surface and press them in gently.","Dock the whole surface thoroughly with a fork to stop it puffing.","Cut into rough rectangles or rounds directly on the parchment.","Bake at 200C for eighteen to twenty minutes until dry and lightly coloured.","Check for any soft, pale patches and return them briefly if needed.","Cool completely on a rack, then store in an airtight tin for weeks."],"blocks":[{"id":"blk_world_051_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Docking the dough with a fork before baking is not decorative. Without those holes the bread puffs unevenly and never crisps flat all the way through.","Roll it as thin as you can manage. Anything thicker than a coin bakes soft in the middle before the surface is properly dry."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_051','Swedish-Style Sesame Crispbread','swedish-rye-style-sesame-crispbread','A thin, docked flatbread baked until it snaps clean, the kind that is meant to keep for weeks in a tin.','crispbread, knackebrod, sesame, Swedish, wheat flour');
