INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_052','World kitchen 052','German Linsen Eintopf Lentil Stew','german-lentil-eintopf','A one-pot lentil stew finished with vinegar, in the German style where a sharp splash at the end is expected, not optional.',15,45,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_052_1','2026-08-16T09:00:00Z','German Linsen Eintopf Lentil Stew — True Grit','A one-pot lentil stew finished with vinegar, in the German style where a sharp splash at the end is expected, not optional.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','linsen eintopf, German lentil stew, vinegar, one pot',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','German Linsen Eintopf Lentil Stew, made with True Grit staples',NULL,'German');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_052_1','rcp_world_052',1,'{"steps":["Warm the oil and cook the onion until softened, about five minutes.","Add the carrots and cook a further five minutes to soften slightly.","Rinse the lentils and add them with the bay leaf and stock.","Bring to the boil, then simmer covered for twenty minutes.","Add the diced potatoes and continue simmering until everything is tender.","Check the lentils have collapsed and the potatoes give no resistance.","Stir in the mustard, tasting as it dissolves through the stew.","Add hot stock if the pot has thickened past a comfortable consistency.","Season generously with salt and pepper, tasting after each addition.","Stir in the vinegar off the heat and let it rest five minutes before serving."],"blocks":[{"id":"blk_world_052_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Eintopf means one pot, and the vegetables go in by how long each takes, added in stages rather than all together.","The vinegar at the end is structural, not a garnish. Without it the stew reads as heavy; a spoonful transforms the whole pot."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_052','German Linsen Eintopf Lentil Stew','german-lentil-eintopf','A one-pot lentil stew finished with vinegar, in the German style where a sharp splash at the end is expected, not optional.','linsen eintopf, German lentil stew, vinegar, one pot');
