INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_053_1','rcp_world_053',1,'{"steps":["Dissolve the yeast in the warm water and leave until it foams.","Mix the flour and salt, then add the yeast water and oil.","Knead for ten minutes until smooth and elastic, then prove one hour.","Divide the dough into eight pieces and shape each into a tight ball.","Rest the shaped balls, covered, for fifteen minutes to relax the dough.","Bring the bicarbonate of soda and water to a gentle simmer in a wide pan.","Dip each roll into the simmering bath for twenty seconds, no longer.","Lift out with a slotted spoon and place on a lined tray immediately.","Score the top of each, then press firmly into the roasted sesame seeds.","Scatter with flaky salt and bake at 220C for twenty minutes until dark."],"blocks":[{"id":"blk_world_053_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The baking soda bath is what makes a pretzel a pretzel rather than a plain bread roll. Skip it and you get a soft bun with a sesame topping and none of the character.","Dip briefly and confidently. Too long in the alkaline bath and the crust turns unpleasantly bitter and overly dark."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_053','German Sesame-Crusted Pretzel Rolls','german-sesame-pretzel-style-rolls','Pretzel-style rolls dipped in a baking soda bath before baking, which is what gives the crust its dark, distinctive chew.','pretzel rolls, sesame crust, German bread, laugengebäck');
