INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_054','World kitchen 054','Polish-Style Toasted Daliya Groats','polish-buckwheat-style-daliya-groats','Daliya toasted dry before it ever meets water, the same technique that gives Polish buckwheat groats their nutty depth.',5,20,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_054_1','2026-08-16T09:00:00Z','Polish-Style Toasted Daliya Groats — True Grit','Daliya toasted dry before it ever meets water, the same technique that gives Polish buckwheat groats their nutty depth.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','kasza style, toasted grain, Polish, daliya, groats',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Polish-Style Toasted Daliya Groats, made with True Grit staples',NULL,'Polish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_054_1','rcp_world_054',1,'{"steps":["Melt the butter and cook the onion until soft and translucent.","Add the dry daliya to the pan without any liquid at this stage.","Toast it, stirring constantly, until it smells nutty and turns a shade darker.","Pour in the water or stock and add the salt in one go.","Bring to the boil, then cover tightly and drop to the lowest heat.","Cook for fifteen minutes without lifting the lid at any point.","Turn off the heat and let it rest, still covered, for ten minutes.","Lift the lid only now and check the grain is fully tender.","Fluff gently with a fork rather than stirring it hard.","Scatter fresh dill over the top and serve while still warm."],"blocks":[{"id":"blk_world_054_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Toasting the grain dry before adding liquid is what buckwheat groats do, and daliya responds to the same trick with real depth.","Use exactly the right water ratio and resist lifting the lid. Steam that escapes early leaves the grain unevenly cooked."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_054','Polish-Style Toasted Daliya Groats','polish-buckwheat-style-daliya-groats','Daliya toasted dry before it ever meets water, the same technique that gives Polish buckwheat groats their nutty depth.','kasza style, toasted grain, Polish, daliya, groats');
