INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_055','World kitchen 055','Hungarian-Style Paprika Lentil Stew','hungarian-lentil-goulash-style-stew','Sweet paprika bloomed in fat off the heat, the single step that separates a proper Hungarian stew from a merely reddish one.',15,40,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_055_1','2026-08-16T09:00:00Z','Hungarian-Style Paprika Lentil Stew — True Grit','Sweet paprika bloomed in fat off the heat, the single step that separates a proper Hungarian stew from a merely reddish one.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','goulash style, paprika, lentils, Hungarian stew',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Hungarian-Style Paprika Lentil Stew, made with True Grit staples',NULL,'Hungarian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_055_1','rcp_world_055',1,'{"steps":["Warm the oil and cook the onions slowly until deeply soft, about fifteen minutes.","Take the pan off the heat completely before the paprika goes in.","Stir the paprika and caraway into the off-heat onions to bloom gently.","Return to low heat and cook for thirty seconds, no more.","Add the peppers and tomatoes and cook for five minutes to soften.","Rinse the lentils and add them with the water or stock.","Bring to the boil, then simmer covered for twenty-five minutes.","Stir occasionally, checking the lentils have softened and collapsed.","Add more hot water if the stew thickens past what you want.","Season generously with salt and pepper and rest before serving."],"blocks":[{"id":"blk_world_055_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Paprika scorches in seconds in hot oil and turns bitter the moment it does. Always add it off the heat, stir it in, then return to a gentle flame.","Use plenty of paprika and use it fresh. A stale tin loses its colour and sweetness and no amount extra will fix that."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_055','Hungarian-Style Paprika Lentil Stew','hungarian-lentil-goulash-style-stew','Sweet paprika bloomed in fat off the heat, the single step that separates a proper Hungarian stew from a merely reddish one.','goulash style, paprika, lentils, Hungarian stew');
