INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_056','World kitchen 056','Russian-Style Daliya Kasha with Mushrooms','russian-buckwheat-style-daliya-kasha','Daliya cooked kasha-style with well-browned mushrooms, where getting a proper sear on the mushrooms is most of the work.',15,30,4,'["vegetarian","vegan"]','published','rcv_world_056_1','2026-08-16T09:00:00Z','Russian-Style Daliya Kasha with Mushrooms — True Grit','Daliya cooked kasha-style with well-browned mushrooms, where getting a proper sear on the mushrooms is most of the work.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','kasha, daliya, mushrooms, Russian, cracked wheat',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Russian-Style Daliya Kasha with Mushrooms, made with True Grit staples',NULL,'Russian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_056_1','rcp_world_056',1,'{"steps":["Heat a wide dry pan until hot before any mushrooms go in.","Add mushrooms in a single uncrowded layer, working in batches if needed.","Leave them undisturbed for several minutes until well browned underneath.","Turn and brown the other side, then set the mushrooms aside.","Warm the oil in the same pan and cook the onion until soft.","Add the dry daliya and toast it briefly, stirring, until fragrant.","Pour in the water or stock and the salt in one addition.","Bring to the boil, cover tightly and drop to the lowest heat.","Cook fifteen minutes without lifting the lid, then rest off heat ten minutes.","Fold the browned mushrooms through and finish with dill and pepper."],"blocks":[{"id":"blk_world_056_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Mushrooms release water before they brown, and a crowded pan traps that water as steam. Cook them in batches so they sear instead of stew.","The daliya itself is simple. Nearly all the character in this dish comes from how patiently the mushrooms are handled."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_056','Russian-Style Daliya Kasha with Mushrooms','russian-buckwheat-style-daliya-kasha','Daliya cooked kasha-style with well-browned mushrooms, where getting a proper sear on the mushrooms is most of the work.','kasha, daliya, mushrooms, Russian, cracked wheat');
