INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_057','World kitchen 057','British-Style Daliya and Flax Flapjack','british-oat-style-daliya-flapjack','A dense, chewy tray bake using daliya in place of oats, held together by melted butter and syrup rather than egg.',15,25,12,'["vegetarian"]','published','rcv_world_057_1','2026-08-16T09:00:00Z','British-Style Daliya and Flax Flapjack — True Grit','A dense, chewy tray bake using daliya in place of oats, held together by melted butter and syrup rather than egg.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','flapjack, daliya, flax, British baking, tray bake',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','British-Style Daliya and Flax Flapjack, made with True Grit staples',NULL,'British');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_057_1','rcp_world_057',1,'{"steps":["Line a square baking tin with parchment, leaving an overhang for lifting.","Melt the butter, syrup and sugar together gently in a pan.","Stir until the sugar has fully dissolved and the mixture is glossy.","Take the pan off the heat and stir in the salt.","Add the daliya and flax seeds, mixing until every grain is coated.","Tip the mixture into the lined tin and spread it out evenly.","Press down firmly with the back of a spoon across the whole surface.","Bake at 160C for twenty-five minutes until golden at the edges.","The centre should still look slightly soft; it will firm as it cools.","Score into bars while warm, then cool fully before cutting through."],"blocks":[{"id":"blk_world_057_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The bake wants to look slightly underdone when it comes out of the oven. It firms up entirely as it cools, and a fully set flapjack out of the oven is an overbaked one.","Press the mixture down firmly and evenly before baking. A loosely packed tray gives crumbly bars that fall apart when cut."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_057','British-Style Daliya and Flax Flapjack','british-oat-style-daliya-flapjack','A dense, chewy tray bake using daliya in place of oats, held together by melted butter and syrup rather than egg.','flapjack, daliya, flax, British baking, tray bake');
