INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_058','World kitchen 058','Scottish-Style Savoury Daliya Porridge','scottish-style-daliya-porridge-savoury','A savoury porridge in the traditional Scottish style, where sugar has no place and salt is stirred in from the start.',5,20,2,'["vegetarian","vegan","gluten free"]','published','rcv_world_058_1','2026-08-16T09:00:00Z','Scottish-Style Savoury Daliya Porridge — True Grit','A savoury porridge in the traditional Scottish style, where sugar has no place and salt is stirred in from the start.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','savoury porridge, daliya, Scottish, salted porridge',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Scottish-Style Savoury Daliya Porridge, made with True Grit staples',NULL,'Scottish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_058_1','rcp_world_058',1,'{"steps":["Bring the water to the boil in a heavy-bottomed pan.","Add the salt to the water before any grain goes in.","Sprinkle in the daliya gradually while stirring constantly.","Drop the heat to a bare simmer once it comes back to a bubble.","Stir regularly in one direction to stop it catching on the base.","Cook for fifteen minutes, watching the texture thicken steadily.","Add a splash more water if it thickens faster than the grain softens.","Taste a spoonful to check the grain is fully tender, not merely swollen.","Rest off the heat, covered, for two minutes before serving.","Finish each bowl with a swirl of oil or a knob of butter."],"blocks":[{"id":"blk_world_058_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Traditional Scottish porridge is salted, never sweetened, and the salt goes in with the water rather than at the table. That single choice changes the whole character.","Stir with a spurtle or a wooden spoon in one direction. It sounds superstitious but it genuinely keeps the texture smoother."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_058','Scottish-Style Savoury Daliya Porridge','scottish-style-daliya-porridge-savoury','A savoury porridge in the traditional Scottish style, where sugar has no place and salt is stirred in from the start.','savoury porridge, daliya, Scottish, salted porridge');
