INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_059','World kitchen 059','Danish-Style Seeded Sesame Loaf','danish-rye-style-sesame-seed-loaf','A dense, heavily seeded loaf in the Danish style, baked in a lidded tin so it stays moist through a long, slow bake.',25,50,12,'["vegetarian","vegan"]','published','rcv_world_059_1','2026-08-16T09:00:00Z','Danish-Style Seeded Sesame Loaf — True Grit','A dense, heavily seeded loaf in the Danish style, baked in a lidded tin so it stays moist through a long, slow bake.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','seeded loaf, Danish bread, sesame seeds, dense bread',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/wheat-flour.webp','Danish-Style Seeded Sesame Loaf, made with True Grit staples',NULL,'Danish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_059_1','rcp_world_059',1,'{"steps":["Toast the plain sesame seeds in a dry pan until golden and fragrant.","Cool completely, because warm seeds soften the dough''s structure.","Dissolve the yeast and honey in the warm water and leave to foam.","Mix the flour, salt and toasted seeds together in a large bowl.","Add the yeast mixture and the oil, bringing it into a sticky dough.","Knead for ten minutes; this dough stays stickier than a white loaf.","Prove covered in a warm place for about ninety minutes until doubled.","Shape into a loaf and place it in a well-oiled lidded loaf tin.","Scatter the roasted sesame seeds over the top and cover with the lid.","Bake at 190C for fifty minutes, removing the lid for the last ten to colour."],"blocks":[{"id":"blk_world_059_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["This loaf is meant to be dense and close-crumbed, not light and airy. A long, gentle bake under cover is what keeps it moist rather than dry.","Toast the sesame seeds before mixing them in. Raw seeds baked inside the loaf taste flat compared with seeds toasted first."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_059','Danish-Style Seeded Sesame Loaf','danish-rye-style-sesame-seed-loaf','A dense, heavily seeded loaf in the Danish style, baked in a lidded tin so it stays moist through a long, slow bake.','seeded loaf, Danish bread, sesame seeds, dense bread');
