INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_060_1','rcp_world_060',1,'{"steps":["Bring the water to a rolling boil in a heavy pan and add the salt.","Reduce to a steady simmer before adding any of the grain.","Rain the daliya in slowly in a thin stream, whisking constantly.","Switch to a wooden spoon once it thickens past whisking easily.","Stir continuously, scraping the base, for twenty to twenty-five minutes.","Watch for it pulling cleanly away from the sides of the pan.","That pulling-away is the real sign it is done, more than the timer.","Beat in the butter until fully melted and glossy through the mixture.","Spoon into bowls immediately, since it firms quickly as it cools.","Top each bowl with crumbled cheese and a spoon of sour cream."],"blocks":[{"id":"blk_world_060_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Real mamaliga is stirred continuously for the better part of half an hour, and there is no shortcut that gives the same smooth result.","Add the grain to already-boiling salted water in a steady rain, never all at once, or it clumps immediately."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_060','Romanian-Style Daliya Mamaliga Bowl','romanian-lentil-mamaliga-style-bowl','A polenta-style bowl using fine daliya instead of cornmeal, stirred constantly the way mamaliga demands.','mamaliga style, polenta style, daliya, Romanian');
