INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_061','World kitchen 061','Persian-Style Lentil and Herb Ash Soup','persian-lentil-ash-style-soup','A thick, herb-heavy Persian-style soup finished with a fried mint and garlic oil poured over at the very last moment.',20,45,6,'["vegetarian","vegan"]','published','rcv_world_061_1','2026-08-16T09:00:00Z','Persian-Style Lentil and Herb Ash Soup — True Grit','A thick, herb-heavy Persian-style soup finished with a fried mint and garlic oil poured over at the very last moment.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','ash-e reshteh style, Persian soup, lentils, herbs',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Persian-Style Lentil and Herb Ash Soup, made with True Grit staples',NULL,'Persian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_061_1','rcp_world_061',1,'{"steps":["Warm two tablespoons of the oil and cook the onion until soft.","Stir in half the garlic and the turmeric, cooking one minute more.","Rinse the lentils and add them with the water, then bring to the boil.","Simmer covered for twenty-five minutes until the lentils are tender.","Add the chopped herbs in stages, stirring each batch down before the next.","Simmer a further fifteen minutes until the herbs have fully wilted in.","Season with salt and pepper, tasting as the herbs continue to soften.","Warm the remaining oil in a small pan just before serving.","Fry the remaining garlic and the dried mint until fragrant and just golden.","Ladle the soup into bowls and pour the hot mint oil over each one."],"blocks":[{"id":"blk_world_061_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The herb quantity looks excessive until you see the finished pot. Persian ash soups are built on herbs, not merely garnished with them.","The fried mint and garlic oil is poured on at the table, in front of whoever is eating, because its aroma fades within minutes of frying."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_061','Persian-Style Lentil and Herb Ash Soup','persian-lentil-ash-style-soup','A thick, herb-heavy Persian-style soup finished with a fried mint and garlic oil poured over at the very last moment.','ash-e reshteh style, Persian soup, lentils, herbs');
