INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_062','World kitchen 062','Persian Sesame Halva Ardeh','persian-sesame-halva-ardeh','A simple Persian tahini halva set with sugar syrup and rosewater, pressed into a tin and cut once it firms.',15,15,12,'["vegetarian","vegan","gluten free"]','published','rcv_world_062_1','2026-08-16T09:00:00Z','Persian Sesame Halva Ardeh — True Grit','A simple Persian tahini halva set with sugar syrup and rosewater, pressed into a tin and cut once it firms.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','halva ardeh, sesame halva, Persian sweet, tahini',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Persian Sesame Halva Ardeh, made with True Grit staples',NULL,'Persian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_062_1','rcp_world_062',1,'{"steps":["Warm the tahini gently over hot water until loose and pourable.","Heat the sugar and water together in a pan without stirring.","Cook to 110C on a thermometer, brushing down any sugar crystals.","Take the syrup off the heat once it reaches a light thread stage.","Pour the hot syrup into the warm tahini in a thin, steady stream.","Stir constantly as you pour so the mixture stays smooth throughout.","Add the rosewater gradually, tasting after each small addition.","Pour into a lined tin and smooth the top with the back of a spoon.","Scatter the chopped pistachios over the surface and press lightly.","Chill for at least three hours until firm, then cut into small pieces."],"blocks":[{"id":"blk_world_062_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The syrup needs to reach a real thread stage before it meets the tahini. Undercooked syrup leaves the halva soft and it never properly sets.","Rosewater is strong. Add it gradually and taste, because too much tips the whole thing towards tasting like soap rather than perfume."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_062','Persian Sesame Halva Ardeh','persian-sesame-halva-ardeh','A simple Persian tahini halva set with sugar syrup and rosewater, pressed into a tin and cut once it firms.','halva ardeh, sesame halva, Persian sweet, tahini');
