INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_063','World kitchen 063','Persian-Style Daliya with Lentils and Dates','persian-daliya-adas-polo-style','Grain and lentils layered with sweet dried fruit and caramelised onions, borrowing the sweet-savoury logic of adas polo.',20,40,5,'["vegetarian","vegan"]','published','rcv_world_063_1','2026-08-16T09:00:00Z','Persian-Style Daliya with Lentils and Dates — True Grit','Grain and lentils layered with sweet dried fruit and caramelised onions, borrowing the sweet-savoury logic of adas polo.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','adas polo style, lentil rice style, daliya, Persian',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Persian-Style Daliya with Lentils and Dates, made with True Grit staples',NULL,'Persian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_063_1','rcp_world_063',1,'{"steps":["Fry the sliced onions slowly in the oil until deeply caramelised, about twenty minutes.","Set most of the onions aside, leaving a little in the pan.","Add the cinnamon and cumin to the pan and stir briefly until fragrant.","Add the daliya and toast it in the spiced oil for two minutes.","Rinse the lentils and add them along with the water and salt.","Bring to the boil, then cover and drop to the lowest possible heat.","Cook for eighteen minutes without lifting the lid at all.","Rest off the heat, still covered, for a further ten minutes.","Warm the dates or raisins briefly in a dry pan to soften them.","Fluff the grain and fold through most of the onions and fruit, saving some to top."],"blocks":[{"id":"blk_world_063_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Persian rice-and-lentil dishes rest on the tension between sweet fruit and savoury spice. The caramelised onions are what carry that balance here.","Cook the onions until properly dark, well past golden. Pale onions leave the dish tasting flat where it should taste rich."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_063','Persian-Style Daliya with Lentils and Dates','persian-daliya-adas-polo-style','Grain and lentils layered with sweet dried fruit and caramelised onions, borrowing the sweet-savoury logic of adas polo.','adas polo style, lentil rice style, daliya, Persian');
