INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_064','World kitchen 064','West African-Style Field Pea Fritters','west-african-black-eyed-pea-fritters','White field peas soaked, skinned and whipped to a fluffy batter, borrowing the akara technique that gives West African fritters their lift.',30,20,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_064_1','2026-08-16T09:00:00Z','West African-Style Field Pea Fritters — True Grit','White field peas soaked, skinned and whipped to a fluffy batter, borrowing the akara technique that gives West African fritters their lift.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','akara style, field pea fritters, West African, black eyed pea',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/white-field-peas.webp','West African-Style Field Pea Fritters, made with True Grit staples',NULL,'West African');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_064_1','rcp_world_064',1,'{"steps":["Drain the soaked peas and rub them between your hands to loosen the skins.","Cover with fresh water and skim off the loosened skins as they float.","Repeat several times until the peas are mostly pale and skin-free.","Drain well and blend with the onion, chilli and a little water.","Blend to a thick, smooth batter, adding water sparingly as needed.","Whip the batter hard with a spoon for several minutes to add air.","It should lighten in colour and roughly double in apparent volume.","Stir in the salt only once the whipping is finished.","Heat oil to a moderate frying temperature and drop in spoonfuls.","Fry until deep golden and puffed, turning each fritter once partway through.","Lift out onto kitchen paper to drain any excess oil before serving warm."],"blocks":[{"id":"blk_world_064_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The skins have to come off. Left on, they weigh the batter down and the fritters end up dense rather than airy.","Whip the batter hard before frying. Air worked into the mixture is what makes these puff up rather than sit flat in the oil."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_064','West African-Style Field Pea Fritters','west-african-black-eyed-pea-fritters','White field peas soaked, skinned and whipped to a fluffy batter, borrowing the akara technique that gives West African fritters their lift.','akara style, field pea fritters, West African, black eyed pea');
INSERT INTO recipe_ingredients (id,recipe_id,label,quantity_text,product_id,sort_order) VALUES ('rci_world_064_01','rcp_world_064','white field peas, soaked overnight','300 g',(SELECT id FROM products WHERE slug='field-pea-white'),1);
