INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_065','World kitchen 065','West African Peanut and Daliya Stew','west-african-sesame-peanut-daliya-stew','A thick peanut-based stew ladled over steamed daliya, where the peanut butter is stirred in gradually so it never splits.',15,45,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_065_1','2026-08-16T09:00:00Z','West African Peanut and Daliya Stew — True Grit','A thick peanut-based stew ladled over steamed daliya, where the peanut butter is stirred in gradually so it never splits.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','groundnut stew style, peanut stew, daliya, West African',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','West African Peanut and Daliya Stew, made with True Grit staples',NULL,'West African');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_065_1','rcp_world_065',1,'{"steps":["Warm the oil and cook the onion, ginger and garlic until fragrant.","Add the tomatoes and chilli, cooking until they break down into a base.","Pour in most of the water or stock and bring to a gentle simmer.","Spoon the peanut butter into a small bowl and loosen it with hot liquid.","Stir the loosened peanut butter into the pot gradually, off the boil.","Return to a very low simmer, stirring often to prevent it catching.","Cook uncovered for twenty-five minutes until visibly thickened.","Meanwhile steam the daliya over simmering water until tender.","Season the stew with salt and adjust the thickness with the remaining water.","Fluff the steamed daliya into bowls and ladle the stew generously over."],"blocks":[{"id":"blk_world_065_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Peanut butter added too fast, or into a pot that is too hot, separates into oil and grit. Stir it in gradually, off the boil, in small additions.","The stew should coat a spoon thickly. If it looks like soup it has not been simmered long enough to concentrate."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
