INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_066','World kitchen 066','Caribbean-Style Lentil Rice and Peas','caribbean-lentil-rice-and-peas-style','Coconut milk rice cooked with whole lentils in place of kidney beans, seasoned with thyme and a whole scotch bonnet for aroma without heat.',15,35,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_066_1','2026-08-16T09:00:00Z','Caribbean-Style Lentil Rice and Peas — True Grit','Coconut milk rice cooked with whole lentils in place of kidney beans, seasoned with thyme and a whole scotch bonnet for aroma without heat.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','rice and peas, Caribbean, coconut, lentils',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Caribbean-Style Lentil Rice and Peas, made with True Grit staples',NULL,'Caribbean');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_066_1','rcp_world_066',1,'{"steps":["Soak the lentils in water for twenty minutes, then drain well.","Simmer the drained lentils in fresh water for fifteen minutes until half tender.","Drain the part-cooked lentils and set them aside.","Warm a little of the coconut milk in a heavy pot and add the garlic.","Cook briefly until fragrant, then add the spring onions and thyme.","Add the rinsed rice, the lentils, remaining coconut milk and water.","Nestle the whole chilli into the pot without piercing or breaking it.","Bring to the boil, then cover tightly and drop to the lowest heat.","Cook for eighteen minutes without lifting the lid at any point.","Rest ten minutes covered, remove the chilli, fluff and season to serve."],"blocks":[{"id":"blk_world_066_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The chilli goes in whole and comes out whole. It perfumes the pot without setting the whole dish on fire, and bursting it by accident changes that completely.","Coconut rice needs a properly tight lid. Steam that escapes during cooking leaves the rice underdone at the centre of the pot."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_066','Caribbean-Style Lentil Rice and Peas','caribbean-lentil-rice-and-peas-style','Coconut milk rice cooked with whole lentils in place of kidney beans, seasoned with thyme and a whole scotch bonnet for aroma without heat.','rice and peas, Caribbean, coconut, lentils');
