INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_067','World kitchen 067','Caribbean Sesame Seed Cake','caribbean-sesame-seed-cake','Toasted sesame set in a caramel until it hardens into a brittle cake, cut while still warm and pliable.',20,20,10,'["vegetarian"]','published','rcv_world_067_1','2026-08-16T09:00:00Z','Caribbean Sesame Seed Cake — True Grit','Toasted sesame set in a caramel until it hardens into a brittle cake, cut while still warm and pliable.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','sesame cake, wangla, Caribbean sweet, sesame seeds',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Caribbean Sesame Seed Cake, made with True Grit staples',NULL,'Caribbean');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_067_1','rcp_world_067',1,'{"steps":["Toast the plain seeds in a dry pan until golden and fragrant throughout.","Keep the toasted seeds warm so they do not cool the caramel too fast.","Heat the sugar and water together in a heavy pan without stirring.","Swirl the pan occasionally as the sugar melts and begins to colour.","Cook until it reaches a deep amber caramel, watching closely near the end.","Stir in the ginger and salt the moment it reaches that colour.","Tip in all the sesame seeds at once and stir quickly to coat them.","Work fast, because the caramel stiffens within about thirty seconds.","Scrape onto oiled parchment and press flat with an oiled rolling pin.","Score into pieces while warm, cool fully, then snap along the lines."],"blocks":[{"id":"blk_world_067_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The caramel stage decides everything. Too pale and the cake will not hold together; too dark and it turns bitter before you can pull it off the heat.","Cut it while still warm and slightly flexible. Once fully cool it hardens completely and shatters unevenly under a knife."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_067','Caribbean Sesame Seed Cake','caribbean-sesame-seed-cake','Toasted sesame set in a caramel until it hardens into a brittle cake, cut while still warm and pliable.','sesame cake, wangla, Caribbean sweet, sesame seeds');
