INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_068','World kitchen 068','Filipino-Style Sesame Daliya Lugaw','filipino-sesame-daliya-lugaw','A savoury rice-porridge-style bowl made with daliya, built on the same garlic and ginger base that opens a Filipino lugaw.',10,40,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_068_1','2026-08-16T09:00:00Z','Filipino-Style Sesame Daliya Lugaw — True Grit','A savoury rice-porridge-style bowl made with daliya, built on the same garlic and ginger base that opens a Filipino lugaw.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','lugaw style, daliya porridge, Filipino, sesame oil',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Filipino-Style Sesame Daliya Lugaw, made with True Grit staples',NULL,'Filipino');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_068_1','rcp_world_068',1,'{"steps":["Warm the oil in a heavy pot and add the sliced garlic and ginger.","Fry gently, stirring, until the garlic turns golden and crisp.","Lift out about half the garlic with a slotted spoon and set aside.","Add the daliya to the remaining garlic and ginger oil and toast briefly.","Pour in the water or stock and bring the pot to a steady boil.","Reduce to a simmer and cook, stirring occasionally, for thirty minutes.","Add more hot water if it thickens past a spoonable consistency too soon.","Stir in the fish sauce and taste before adding any extra salt.","Season with black pepper and simmer a further five minutes.","Ladle into bowls, scatter the reserved crisp garlic on top, and finish with lime."],"blocks":[{"id":"blk_world_068_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The garlic oil made at the start does two jobs: it flavours the porridge base and becomes the crisp topping scattered over each bowl at the end.","Cook the fried garlic separately from the porridge itself, and set some aside before it browns too far, so you have both a mellow base and a crisp topping."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_068','Filipino-Style Sesame Daliya Lugaw','filipino-sesame-daliya-lugaw','A savoury rice-porridge-style bowl made with daliya, built on the same garlic and ginger base that opens a Filipino lugaw.','lugaw style, daliya porridge, Filipino, sesame oil');
