INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_069','World kitchen 069','Indonesian Gado-Gado Style Sesame Peanut Sauce','indonesian-gado-gado-sesame-peanut-sauce','A rich peanut and sesame sauce for steamed vegetables, thinned with hot water until it coats rather than clumps.',15,10,6,'["vegetarian","vegan","gluten free"]','published','rcv_world_069_1','2026-08-16T09:00:00Z','Indonesian Gado-Gado Style Sesame Peanut Sauce — True Grit','A rich peanut and sesame sauce for steamed vegetables, thinned with hot water until it coats rather than clumps.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','gado gado, peanut sauce, sesame, Indonesian, salad sauce',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Indonesian Gado-Gado Style Sesame Peanut Sauce, made with True Grit staples',NULL,'Indonesian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_069_1','rcp_world_069',1,'{"steps":["Grind the peanuts and sesame seeds together to a coarse, oily paste.","Warm the oil in a small pan and fry the garlic and chilli briefly.","Add the ground peanut and sesame mixture and stir to combine.","Stir in the sugar and tamarind, cooking gently for two minutes.","Add hot water gradually, stirring constantly between each addition.","Stop adding water once the sauce coats the back of a spoon thickly.","Season with salt, tasting for the sweet, sour and savoury balance.","Simmer very gently for a further two minutes to let the flavours settle.","Adjust with more lime juice if the sauce tastes flat rather than bright.","Serve warm, spooned generously over steamed vegetables and daliya."],"blocks":[{"id":"blk_world_069_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The sauce is meant to be thick enough to cling to steamed vegetables, not to pour like a dressing. Loosen it gradually and stop before it turns watery.","Roasting the peanuts freshly, rather than using a jar of peanut butter alone, is what gives this its proper depth."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_069','Indonesian Gado-Gado Style Sesame Peanut Sauce','indonesian-gado-gado-sesame-peanut-sauce','A rich peanut and sesame sauce for steamed vegetables, thinned with hot water until it coats rather than clumps.','gado gado, peanut sauce, sesame, Indonesian, salad sauce');
