INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_070','World kitchen 070','Malaysian-Style Sesame Marinade for Grilled Vegetables','malaysian-sesame-flax-satay-marinade','A satay-inspired sesame and spice marinade for grilled vegetables, built to caramelise rather than burn on the grill.',15,15,6,'["vegetarian","vegan","gluten free"]','published','rcv_world_070_1','2026-08-16T09:00:00Z','Malaysian-Style Sesame Marinade for Grilled Vegetables — True Grit','A satay-inspired sesame and spice marinade for grilled vegetables, built to caramelise rather than burn on the grill.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','satay style marinade, sesame, Malaysian, grilled vegetables',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Malaysian-Style Sesame Marinade for Grilled Vegetables, made with True Grit staples',NULL,'Malaysian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_070_1','rcp_world_070',1,'{"steps":["Whisk the oil, ground sesame, coriander, cumin and turmeric together.","Stir in the sugar, soy sauce, garlic, ginger and lime juice.","Taste and balance: more lime if it feels heavy, more sugar if too sharp.","Cut the vegetables or paneer into pieces suited to skewering.","Toss thoroughly in the marinade, making sure every surface is coated.","Cover and refrigerate for at least one hour, longer if you have time.","Thread onto skewers if using, leaving a little space between pieces.","Grill over medium heat, turning often to avoid the sugar scorching.","Baste with any leftover marinade during the first few turns only.","Cook until charred at the edges and tender through, then serve hot."],"blocks":[{"id":"blk_world_070_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Sugar in a marinade caramelises beautifully but burns fast on high heat. Grill over medium heat and turn often rather than leaving it over the hottest part.","Marinate for at least an hour if you can manage it. A rushed fifteen-minute soak barely reaches the surface of what you are grilling."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_070','Malaysian-Style Sesame Marinade for Grilled Vegetables','malaysian-sesame-flax-satay-marinade','A satay-inspired sesame and spice marinade for grilled vegetables, built to caramelise rather than burn on the grill.','satay style marinade, sesame, Malaysian, grilled vegetables');
