INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_071','World kitchen 071','Indonesian-Style Sambal Lentil Stew','indonesian-lentil-sambal-style-stew','A chilli and shallot paste fried until the oil separates, the same base technique behind most Indonesian sambal dishes, built around lentils here.',20,35,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_071_1','2026-08-16T09:00:00Z','Indonesian-Style Sambal Lentil Stew — True Grit','A chilli and shallot paste fried until the oil separates, the same base technique behind most Indonesian sambal dishes, built around lentils here.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','sambal style, lentil stew, Indonesian, chilli paste',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Indonesian-Style Sambal Lentil Stew, made with True Grit staples',NULL,'Indonesian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_071_1','rcp_world_071',1,'{"steps":["Blend the shallots, garlic, chillies and tomato to a smooth paste.","Warm the oil in a wide pan over medium heat until shimmering.","Add the paste and fry, stirring often, for eight to ten minutes.","Watch for the oil visibly separating out around the edges of the paste.","Stir in the sugar once the paste has darkened and the oil has split.","Rinse the lentils and add them to the fried paste, stirring to coat.","Pour in the water and bring the pot to a steady simmer.","Cook uncovered for twenty minutes, stirring occasionally as it thickens.","Add more hot water if it thickens past a comfortable consistency.","Season with salt to taste and rest five minutes before serving."],"blocks":[{"id":"blk_world_071_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["A proper sambal base is fried until you see the oil separate out around the edges of the paste. That visible separation is the actual doneness signal, not a timer.","Blend the paste smooth before frying. A coarse paste fries unevenly, with some pieces burning while others stay raw."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_071','Indonesian-Style Sambal Lentil Stew','indonesian-lentil-sambal-style-stew','A chilli and shallot paste fried until the oil separates, the same base technique behind most Indonesian sambal dishes, built around lentils here.','sambal style, lentil stew, Indonesian, chilli paste');
