INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_072','World kitchen 072','Australian Damper-Style Sesame Bread','australian-damper-style-sesame-bread','A rustic no-yeast bread baked as one round loaf, scored deeply so the inside cooks through before the crust burns.',10,35,8,'["vegetarian"]','published','rcv_world_072_1','2026-08-16T09:00:00Z','Australian Damper-Style Sesame Bread — True Grit','A rustic no-yeast bread baked as one round loaf, scored deeply so the inside cooks through before the crust burns.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','damper, sesame bread, Australian, no-yeast bread',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/wheat-flour.webp','Australian Damper-Style Sesame Bread, made with True Grit staples',NULL,'Australian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_072_1','rcp_world_072',1,'{"steps":["Combine the flour, baking powder and salt in a large bowl.","Rub the oil through the flour until it resembles coarse crumbs.","Add the milk gradually, stopping once the dough just comes together.","Handle the dough as little as possible from this point onward.","Shape it into a round on a baking tray, flattening it gently.","Score a deep cross well into the loaf, most of the way through.","Brush the surface with a little milk or water to help the seeds stick.","Press the roasted sesame seeds firmly over the top of the loaf.","Bake at 200C for thirty-five minutes until deeply golden and hollow-sounding.","Cool on a rack for at least fifteen minutes before slicing."],"blocks":[{"id":"blk_world_072_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Damper is a soda bread relative with no proving time, which makes it forgiving and quick. The trade-off is a denser crumb than a yeasted loaf.","Score it deeply, well into the dough, not just across the surface. A shallow score does nothing to help the centre cook through in time."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_072','Australian Damper-Style Sesame Bread','australian-damper-style-sesame-bread','A rustic no-yeast bread baked as one round loaf, scored deeply so the inside cooks through before the crust burns.','damper, sesame bread, Australian, no-yeast bread');
