INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_073_1','rcp_world_073',1,'{"steps":["Drain the soaked peas and rub them firmly between your palms.","Cover with fresh water and skim off the loosened skins as they float.","Repeat the rinsing and skimming until most of the skins are gone.","Drain thoroughly and blend the peas with the onion and a little water.","Blend to a thick, smooth batter, adding water sparingly as needed.","Whip the batter by hand for several minutes to work in air.","It should lighten and increase noticeably in apparent volume.","Stir in the salt only at the end, once the whipping is done.","Heat the sesame oil to a moderate frying temperature in a deep pan.","Fry spoonfuls of batter until deep golden brown and visibly puffed up.","Lift out onto kitchen paper to drain briefly, then serve while hot."],"blocks":[{"id":"blk_world_073_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The dish this borrows from is normally fried in dendê palm oil for its distinctive red colour and flavour. This version uses sesame oil instead and is honest about that substitution rather than claiming to be traditional.","Skinning the peas thoroughly is what gives the batter its characteristic light, airy texture once fried."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_073','Brazilian-Style Field Pea Fritters','brazilian-black-eyed-pea-acaraje-style','Skinned field pea fritters fried in a well-seasoned oil, related closely to Brazil''s acaraje but skipping the traditional palm oil.','acaraje style, field pea fritters, Brazilian, black eyed pea');
