INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_074','World kitchen 074','Brazilian-Style Sesame Farofa Topping','brazilian-sesame-farofa-style-topping','A toasted, savoury sesame and semolina topping in the spirit of farofa, meant to be scattered generously over a finished dish.',10,15,8,'["vegetarian","vegan"]','published','rcv_world_074_1','2026-08-16T09:00:00Z','Brazilian-Style Sesame Farofa Topping — True Grit','A toasted, savoury sesame and semolina topping in the spirit of farofa, meant to be scattered generously over a finished dish.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','farofa style, toasted topping, sesame, Brazilian',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Brazilian-Style Sesame Farofa Topping, made with True Grit staples',NULL,'Brazilian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_074_1','rcp_world_074',1,'{"steps":["Melt the butter in a wide pan over low to medium heat.","Add the diced onion and cook until soft, not coloured.","Add the sesame seeds first and toast briefly until fragrant.","Stir in the semolina and reduce the heat to low from here.","Toast the mixture slowly, stirring constantly and without pause.","Watch closely as it turns from pale to golden across the pan.","Take it off the heat the moment it reaches an even golden colour.","Continue stirring off the heat for a minute, since the pan stays hot.","Season with salt, tasting once it has cooled slightly.","Cool completely and store airtight, scattering over rice or stews to serve."],"blocks":[{"id":"blk_world_074_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Farofa is a toasted cassava-flour topping; this version uses semolina and sesame, and is offered as a topping in that spirit rather than a claim to be the traditional dish.","Toast slowly and stir constantly. Semolina and sesame both go from golden to burnt within seconds of each other once they start to colour."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_074','Brazilian-Style Sesame Farofa Topping','brazilian-sesame-farofa-style-topping','A toasted, savoury sesame and semolina topping in the spirit of farofa, meant to be scattered generously over a finished dish.','farofa style, toasted topping, sesame, Brazilian');
