INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_075','World kitchen 075','Sri Lankan-Style Daliya Coconut Mallum','sri-lankan-sesame-daliya-coconut-mallum','Daliya finished with grated coconut and a hard tempering of mustard seed and curry leaf, the technique that defines a Sri Lankan mallum.',15,20,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_075_1','2026-08-16T09:00:00Z','Sri Lankan-Style Daliya Coconut Mallum — True Grit','Daliya finished with grated coconut and a hard tempering of mustard seed and curry leaf, the technique that defines a Sri Lankan mallum.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','mallum style, coconut, daliya, Sri Lankan, tempered spices',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Sri Lankan-Style Daliya Coconut Mallum, made with True Grit staples',NULL,'Sri Lankan');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_075_1','rcp_world_075',1,'{"steps":["Rinse the daliya and simmer it in the water with the turmeric and salt.","Cook for eighteen minutes until fully tender, then drain any excess water.","Warm the oil in a separate pan over medium-high heat.","Add the mustard seeds and wait until they crackle and pop properly.","Add the curry leaves and dried chillies, standing back as they spit.","Cook for thirty seconds until the curry leaves turn crisp.","Add the cooked daliya to the tempered oil and toss to coat evenly.","Cook for two minutes, stirring, so the grain takes up the aroma.","Take the pan off the heat completely before the coconut goes in.","Fold the coconut through off the heat and serve immediately while warm."],"blocks":[{"id":"blk_world_075_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The tempering has to crackle properly before anything else goes in. Mustard seeds that only warm through, rather than pop, leave the whole dish tasting raw.","Coconut goes in at the very end and off the heat, so it stays fresh and slightly crisp rather than turning soft and oily."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_075','Sri Lankan-Style Daliya Coconut Mallum','sri-lankan-sesame-daliya-coconut-mallum','Daliya finished with grated coconut and a hard tempering of mustard seed and curry leaf, the technique that defines a Sri Lankan mallum.','mallum style, coconut, daliya, Sri Lankan, tempered spices');
