INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_076_1','rcp_world_076',1,'{"steps":["Boil the vermicelli until just tender, then drain and rinse cold.","Toss with a tablespoon of the sesame oil to keep the strands separate.","Fry the sliced shallots slowly in a little oil until crisp and golden.","Drain the fried shallots on paper and reserve the flavoured oil.","Combine the noodles, cabbage and half the peanuts in a wide bowl.","Add the lime juice, fish sauce, remaining sesame oil and chilli flakes.","Use clean hands to massage everything together for a full minute.","Taste and adjust the lime, salt and chilli until the balance feels right.","Pile onto plates and scatter the crisp shallots and remaining peanuts over.","Finish with the roasted sesame seeds and serve immediately."],"blocks":[{"id":"blk_world_076_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Burmese salads are traditionally mixed by hand, massaging the ingredients rather than stirring them with a spoon. That method genuinely coats every strand better than tossing does.","Balance sour, salty and a little sweet against each other by taste at the end, since noodle thickness and lime sharpness vary too much for a fixed measure."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_076','Burmese-Style Sesame Oil Vermicelli Salad','burmese-sesame-oil-thoke-style-salad','A tossed noodle salad in the Burmese thoke style, hand-mixed rather than stirred, which is what actually coats every strand.','thoke style, Burmese salad, vermicelli, sesame oil');
