INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_077','World kitchen 077','Ghanaian-Style Jollof Daliya','ghanaian-sesame-daliya-jollof-style','A jollof-style tomato and pepper base cooked down hard before the daliya goes in, borrowing the technique rather than claiming to be jollof rice.',20,45,5,'["vegetarian","vegan","gluten free"]','published','rcv_world_077_1','2026-08-16T09:00:00Z','Ghanaian-Style Jollof Daliya — True Grit','A jollof-style tomato and pepper base cooked down hard before the daliya goes in, borrowing the technique rather than claiming to be jollof rice.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','jollof style, daliya, Ghanaian, one-pot grain',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Ghanaian-Style Jollof Daliya, made with True Grit staples',NULL,'Ghanaian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_077_1','rcp_world_077',1,'{"steps":["Blend the tomatoes and peppers together to a smooth, thick puree.","Warm the oil and fry the onion until soft and lightly coloured.","Add the blended puree and cook it down hard, stirring often.","Continue until the mixture darkens and the raw smell fully disappears.","Stir in the thyme, curry powder and bay leaves until fragrant.","Add the daliya and toast it in the reduced sauce for two minutes.","Pour in the stock and season with salt and chilli to taste.","Bring to the boil, then cover tightly and drop to the lowest heat.","Cook for twenty minutes without lifting the lid at any point.","Rest ten minutes covered, fluff with a fork, and serve hot."],"blocks":[{"id":"blk_world_077_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The tomato and pepper base needs to fry down until it darkens and the raw smell is completely gone. A watery, pale base gives a bland result whatever seasoning you add later.","Resist stirring once the daliya is in and the lid is on. Every lift of the lid lets steam escape that the grain needs to cook evenly."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_077','Ghanaian-Style Jollof Daliya','ghanaian-sesame-daliya-jollof-style','A jollof-style tomato and pepper base cooked down hard before the daliya goes in, borrowing the technique rather than claiming to be jollof rice.','jollof style, daliya, Ghanaian, one-pot grain');
