INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_078','World kitchen 078','Egyptian-Style Koshari Lentil Pasta','egyptian-koshari-style-lentil-pasta','Pasta, rice and lentils layered under a sharp tomato sauce and a mountain of crisp fried onion, cooked as three separate components.',25,40,5,'["vegetarian","vegan"]','published','rcv_world_078_1','2026-08-16T09:00:00Z','Egyptian-Style Koshari Lentil Pasta — True Grit','Pasta, rice and lentils layered under a sharp tomato sauce and a mountain of crisp fried onion, cooked as three separate components.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','koshari, lentil pasta, Egyptian, layered rice dish',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/whole-wheat-pasta.webp','Egyptian-Style Koshari Lentil Pasta, made with True Grit staples',NULL,'Egyptian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_078_1','rcp_world_078',1,'{"steps":["Fry the sliced onions slowly in plenty of oil until deeply crisp.","Drain on paper and set aside; this is the single most important step.","Cook the pasta separately until just tender, then drain and set aside.","Simmer the rinsed lentils in water for twenty minutes until tender, drain.","Cook the rice separately in salted water until fluffy, then fluff it.","Warm oil and fry the garlic briefly, then add the tomatoes and cumin.","Simmer the tomato sauce for fifteen minutes until thickened and glossy.","Stir the chilli flakes and vinegar into the sauce off the heat.","Layer rice, lentils and pasta together in a wide serving dish.","Spoon the tomato sauce over generously and top with the crisp onions."],"blocks":[{"id":"blk_world_078_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Koshari is three components cooked separately and layered at the end, never combined in one pot. Trying to shortcut that gives a mush instead of distinct layers.","The fried onions have to be genuinely crisp, not merely browned, because they are the textural centrepiece of the whole dish."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_078','Egyptian-Style Koshari Lentil Pasta','egyptian-koshari-style-lentil-pasta','Pasta, rice and lentils layered under a sharp tomato sauce and a mountain of crisp fried onion, cooked as three separate components.','koshari, lentil pasta, Egyptian, layered rice dish');
