INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_079','World kitchen 079','Egyptian Sesame Tahini and Honey Dip','egyptian-sesame-tahini-halawa-dip','A two-ingredient breakfast dip that separates into swirls rather than blending smooth, which is exactly how it should look.',5,5,8,'["vegetarian","gluten free"]','published','rcv_world_079_1','2026-08-16T09:00:00Z','Egyptian Sesame Tahini and Honey Dip — True Grit','A two-ingredient breakfast dip that separates into swirls rather than blending smooth, which is exactly how it should look.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tahini honey dip, sesame, Egyptian breakfast',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Egyptian Sesame Tahini and Honey Dip, made with True Grit staples',NULL,'Egyptian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_079_1','rcp_world_079',1,'{"steps":["Warm the honey briefly if it has become thick or crystallised.","Spoon the tahini into a shallow serving dish and level the surface.","Season the tahini lightly with the pinch of salt and stir once.","Drizzle the warm honey over the tahini in a loose spiral pattern.","Drag a spoon or knife through in a few strokes to create marbled swirls.","Stop before the two fully combine into a single uniform colour.","Scatter the roasted sesame seeds over the swirled surface.","Serve immediately alongside warm flatbread for tearing and scooping.","Stir gently before each use if the dip has settled between servings.","Store any leftovers airtight and re-swirl lightly before serving again."],"blocks":[{"id":"blk_world_079_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Tahini and honey are meant to swirl together, not emulsify into one uniform colour. Overmixing loses the visual contrast that is part of the appeal.","Warm the honey slightly if it has crystallised. Cold, hard honey will not fold into the tahini evenly."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_079','Egyptian Sesame Tahini and Honey Dip','egyptian-sesame-tahini-halawa-dip','A two-ingredient breakfast dip that separates into swirls rather than blending smooth, which is exactly how it should look.','tahini honey dip, sesame, Egyptian breakfast');
