INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_080','World kitchen 080','Israeli-Style Red Lentil Shakshuka','israeli-red-lentil-shakshuka','Red lentils thicken a classic shakshuka sauce so the eggs poach in something closer to stew than watery tomato.',10,35,4,'["vegetarian","gluten free"]','published','rcv_world_080_1','2026-08-16T09:00:00Z','Israeli-Style Red Lentil Shakshuka — True Grit','Red lentils thicken a classic shakshuka sauce so the eggs poach in something closer to stew than watery tomato.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','shakshuka, red lentils, Israeli, eggs poached in sauce',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Israeli-Style Red Lentil Shakshuka, made with True Grit staples',NULL,'Israeli');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_080_1','rcp_world_080',1,'{"steps":["Warm the oil and cook the onion and pepper together until soft.","Add the garlic, cumin and paprika, stirring one minute until fragrant.","Rinse the lentils and add them with the chopped tomatoes.","Add a splash of water and bring the pan to a steady simmer.","Cook uncovered for twenty minutes, stirring, until the lentils collapse.","Season with salt and adjust the thickness with a little more water.","Use a spoon to make four small wells in the surface of the sauce.","Crack an egg into each well without breaking the yolk.","Cover and cook gently until the whites are set but yolks still soft.","Scatter with coriander and serve straight from the pan while hot."],"blocks":[{"id":"blk_world_080_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Make small wells for the eggs rather than cracking them straight onto the surface. A defined well keeps the whites from spreading thin across the whole pan.","Cover the pan while the eggs poach, but check often. Shakshuka eggs go from just-set to hard in a very short window."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_080','Israeli-Style Red Lentil Shakshuka','israeli-red-lentil-shakshuka','Red lentils thicken a classic shakshuka sauce so the eggs poach in something closer to stew than watery tomato.','shakshuka, red lentils, Israeli, eggs poached in sauce');
