INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_081','World kitchen 081','Israeli-Style Toasted Daliya with Vegetables','israeli-sesame-couscous-style-daliya','Daliya toasted in oil until it browns before liquid is added, borrowing the technique that gives Israeli toasted couscous its nutty depth.',20,25,5,'["vegetarian","vegan"]','published','rcv_world_081_1','2026-08-16T09:00:00Z','Israeli-Style Toasted Daliya with Vegetables — True Grit','Daliya toasted in oil until it browns before liquid is added, borrowing the technique that gives Israeli toasted couscous its nutty depth.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','toasted grain, ptitim style, daliya, Israeli',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Israeli-Style Toasted Daliya with Vegetables, made with True Grit staples',NULL,'Israeli');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_081_1','rcp_world_081',1,'{"steps":["Warm the oil in a wide pan and add the dry daliya directly.","Toast it over medium heat, stirring constantly, for six to eight minutes.","Watch for a proper golden-brown colour, well past a light toast.","Add the onion and carrot and cook a further five minutes.","Pour in the stock and bring the pan to a steady simmer.","Cover and cook for fifteen minutes until the daliya is nearly tender.","Stir in the courgette and cook a further five minutes, uncovered.","Add the cherry tomatoes in the last two minutes so they barely soften.","Season generously with salt and pepper, tasting as you go.","Fold through the parsley and serve warm as a main or side."],"blocks":[{"id":"blk_world_081_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The browning stage is the whole point, and it takes longer than expected. A pale, barely toasted grain gives a much flatter finished dish.","Add the vegetables in stages by how long they take to cook, rather than all at once, so nothing turns to mush before the rest is ready."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_081','Israeli-Style Toasted Daliya with Vegetables','israeli-sesame-couscous-style-daliya','Daliya toasted in oil until it browns before liquid is added, borrowing the technique that gives Israeli toasted couscous its nutty depth.','toasted grain, ptitim style, daliya, Israeli');
