INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_082','World kitchen 082','Armenian-Style Daliya and Lentil Pilaf','armenian-lentil-bulgur-style-pilaf','A simple grain and lentil pilaf built on a properly caramelised onion base, closer to Armenian home cooking than to any restaurant version.',15,35,5,'["vegetarian","vegan"]','published','rcv_world_082_1','2026-08-16T09:00:00Z','Armenian-Style Daliya and Lentil Pilaf — True Grit','A simple grain and lentil pilaf built on a properly caramelised onion base, closer to Armenian home cooking than to any restaurant version.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','bulgur pilaf style, daliya, lentils, Armenian',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Armenian-Style Daliya and Lentil Pilaf, made with True Grit staples',NULL,'Armenian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_082_1','rcp_world_082',1,'{"steps":["Warm the oil and cook the onion slowly until deeply golden brown.","Stir in the tomato paste and cook for one minute until darkened.","Add the daliya and toast it in the paste for two minutes.","Rinse the lentils and add them along with the water and salt.","Bring to the boil, then cover tightly and drop to the lowest heat.","Cook for eighteen minutes without lifting the lid at any point.","Turn off the heat and let it rest, covered, for a further ten minutes.","Lift the lid only now, once the resting time has finished.","Fluff gently with a fork rather than stirring it firmly.","Season with black pepper and serve warm as a main dish."],"blocks":[{"id":"blk_world_082_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The onions want real colour, cooked well past soft into a deep golden brown, because they carry most of the dish''s flavour.","Rest the pilaf covered off the heat once cooked. That resting time is what lets the grain finish absorbing steam evenly."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_082','Armenian-Style Daliya and Lentil Pilaf','armenian-lentil-bulgur-style-pilaf','A simple grain and lentil pilaf built on a properly caramelised onion base, closer to Armenian home cooking than to any restaurant version.','bulgur pilaf style, daliya, lentils, Armenian');
