INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_083','World kitchen 083','Georgian-Style Cornmeal and Daliya Flatbread','georgian-sesame-walnut-daliya-mchadi','A rustic pan-fried flatbread borrowing mchadi''s cornmeal base, with fine daliya added for a slightly different texture.',15,20,6,'["vegetarian"]','published','rcv_world_083_1','2026-08-16T09:00:00Z','Georgian-Style Cornmeal and Daliya Flatbread — True Grit','A rustic pan-fried flatbread borrowing mchadi''s cornmeal base, with fine daliya added for a slightly different texture.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','mchadi style, cornmeal flatbread, Georgian, daliya',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/wheat-flour.webp','Georgian-Style Cornmeal and Daliya Flatbread, made with True Grit staples',NULL,'Georgian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_083_1','rcp_world_083',1,'{"steps":["Combine the cornmeal, daliya and salt in a mixing bowl.","Pour in the hot water gradually, stirring to a thick, pliable batter.","Rest the batter for ten minutes so the daliya softens slightly.","Divide into six portions and flatten each into a rough disc.","If filling with cheese, press a portion into the centre and seal.","Warm a little oil in a heavy pan over medium heat.","Cook each flatbread for four to five minutes on the first side.","Flip and cook the second side until both sides are well browned.","Press gently with a spatula to check the centre feels fully cooked.","Serve warm straight from the pan, ideally with more butter or oil."],"blocks":[{"id":"blk_world_083_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The batter needs to be thick enough to hold its shape but wet enough to spread easily. Too dry and the centre stays raw before the outside browns.","Cook in a well-oiled pan over medium heat, not high. High heat browns the outside before the middle has any chance to cook through."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_083','Georgian-Style Cornmeal and Daliya Flatbread','georgian-sesame-walnut-daliya-mchadi','A rustic pan-fried flatbread borrowing mchadi''s cornmeal base, with fine daliya added for a slightly different texture.','mchadi style, cornmeal flatbread, Georgian, daliya');
