INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_084','World kitchen 084','Irish-Style Daliya Soda Farls','irish-daliya-soda-farls','A quick griddle bread cut into quarters, using fine daliya alongside flour for extra texture in the classic Irish farl shape.',10,20,4,'["vegetarian"]','published','rcv_world_084_1','2026-08-16T09:00:00Z','Irish-Style Daliya Soda Farls — True Grit','A quick griddle bread cut into quarters, using fine daliya alongside flour for extra texture in the classic Irish farl shape.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','soda farls, Irish bread, daliya, griddle bread',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Irish-Style Daliya Soda Farls, made with True Grit staples',NULL,'Irish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_084_1','rcp_world_084',1,'{"steps":["Combine the flour, daliya, bicarbonate of soda and salt in a bowl.","Make a well in the centre and pour in most of the buttermilk.","Bring together quickly with a knife, adding more buttermilk if too dry.","Turn out and pat gently into a round about two centimetres thick.","Cut the round into four even quarters, or farls, with a sharp knife.","Warm a griddle or heavy pan over medium heat with a little oil.","Cook the farls for five to six minutes on the first side.","Flip carefully and cook the second side for the same time.","Check doneness by tapping the base, which should sound hollow.","Cool briefly on a rack and serve warm, split and buttered."],"blocks":[{"id":"blk_world_084_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Handle the dough as little as possible. Every extra minute of kneading toughens what should be a tender, quick bread.","Cook on the griddle rather than in the oven. That direct contact is what gives farls their characteristic charred, blistered surface."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_084','Irish-Style Daliya Soda Farls','irish-daliya-soda-farls','A quick griddle bread cut into quarters, using fine daliya alongside flour for extra texture in the classic Irish farl shape.','soda farls, Irish bread, daliya, griddle bread');
