INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_085','World kitchen 085','Iraqi-Style Lentil and Bread Tashreeb','iraqi-lentil-tashreeb-style-stew','A lentil stew ladled hot over torn flatbread until it softens and drinks the broth, the way tashreeb is traditionally served.',15,40,4,'["vegetarian","vegan"]','published','rcv_world_085_1','2026-08-16T09:00:00Z','Iraqi-Style Lentil and Bread Tashreeb — True Grit','A lentil stew ladled hot over torn flatbread until it softens and drinks the broth, the way tashreeb is traditionally served.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tashreeb style, lentil stew, Iraqi, bread soaked in broth',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Iraqi-Style Lentil and Bread Tashreeb, made with True Grit staples',NULL,'Iraqi');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_085_1','rcp_world_085',1,'{"steps":["Warm the oil and cook the onion until soft and lightly coloured.","Add the garlic, cumin and turmeric, stirring one minute until fragrant.","Rinse the lentils and add them with the stock to the pot.","Bring to the boil and skim off any foam that rises.","Simmer partly covered for thirty minutes until the lentils are tender.","Tear the flatbread into rough pieces and arrange them in serving bowls.","Ladle the hot lentil stew directly over the torn bread while it is hot.","Let it sit for two minutes so the bread absorbs the broth properly.","Check the bread has softened but not fully disintegrated.","Finish with a squeeze of lemon and fresh mint, then serve at once."],"blocks":[{"id":"blk_world_085_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The bread should be added just before serving, not cooked in the pot. It needs only a few minutes of hot broth to soften properly without disintegrating.","Tear the bread rather than cutting it. Torn edges soak up broth more readily than a clean-cut surface."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_085','Iraqi-Style Lentil and Bread Tashreeb','iraqi-lentil-tashreeb-style-stew','A lentil stew ladled hot over torn flatbread until it softens and drinks the broth, the way tashreeb is traditionally served.','tashreeb style, lentil stew, Iraqi, bread soaked in broth');
