INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_086','World kitchen 086','Uzbek-Style Daliya Plov with Carrots','uzbek-sesame-daliya-plov-style','Carrots cut into thick matchsticks and cooked down until sweet, the base that gives Uzbek plov its distinctive orange-tinted depth.',20,45,6,'["vegetarian","vegan","gluten free"]','published','rcv_world_086_1','2026-08-16T09:00:00Z','Uzbek-Style Daliya Plov with Carrots — True Grit','Carrots cut into thick matchsticks and cooked down until sweet, the base that gives Uzbek plov its distinctive orange-tinted depth.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','plov style, daliya, carrots, Uzbek pilaf',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Uzbek-Style Daliya Plov with Carrots, made with True Grit staples',NULL,'Uzbek');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_086_1','rcp_world_086',1,'{"steps":["Warm the oil in a heavy pot and fry the onion until golden.","Add the carrots and cook slowly, stirring occasionally, for ten minutes.","Continue until the carrots have softened and turned noticeably sweeter.","Stir in the cumin and cook briefly until the aroma lifts.","Nestle the halved garlic head, cut side down, into the vegetables.","Add the water or stock and bring the pot to a simmer.","Scatter the daliya over the top in an even layer without stirring it in.","Cover tightly and cook on the lowest heat for twenty-five minutes.","Resist lifting the lid or stirring during this time.","Rest ten minutes covered, then fold everything together gently to serve."],"blocks":[{"id":"blk_world_086_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The carrots are cut thick, not fine, and cooked slowly until they soften and release sweetness into the oil. Thin carrots dissolve too fast and give a different result entirely.","Layer the daliya over the vegetables without stirring it in. Real plov is built in undisturbed layers, and stirring at this stage works against the texture you want."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_086','Uzbek-Style Daliya Plov with Carrots','uzbek-sesame-daliya-plov-style','Carrots cut into thick matchsticks and cooked down until sweet, the base that gives Uzbek plov its distinctive orange-tinted depth.','plov style, daliya, carrots, Uzbek pilaf');
