INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_087','World kitchen 087','Ukrainian-Style Daliya Filling for Dumplings','ukrainian-sesame-daliya-varenyky-filling','A savoury mashed daliya and cheese filling in the spirit of varenyky, spoonable on its own or folded into dumpling dough.',20,25,6,'["vegetarian"]','published','rcv_world_087_1','2026-08-16T09:00:00Z','Ukrainian-Style Daliya Filling for Dumplings — True Grit','A savoury mashed daliya and cheese filling in the spirit of varenyky, spoonable on its own or folded into dumpling dough.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','varenyky filling, daliya, dumpling filling, Ukrainian',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Ukrainian-Style Daliya Filling for Dumplings, made with True Grit staples',NULL,'Ukrainian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_087_1','rcp_world_087',1,'{"steps":["Rinse the daliya and simmer it in salted water until fully tender.","Drain thoroughly in a sieve, pressing gently to remove excess water.","Warm the butter and cook the onion until soft and lightly golden.","Combine the drained daliya with the cooked onion in a bowl.","Mash lightly with a fork so the mixture holds together but keeps texture.","Stir in the grated cheese while the mixture is still warm enough to melt it.","Season generously with salt and black pepper, tasting as you go.","Fold most of the dill through, saving a little for the top.","Serve warm as a spoonable side, topped with sour cream and dill.","Alternatively cool completely and use as a dumpling filling."],"blocks":[{"id":"blk_world_087_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The filling needs to be dry enough to hold its shape in a dumpling wrapper without weeping liquid, which is why the cooked daliya is drained thoroughly before mixing.","This is offered as a filling on its own, spoonable and complete, or as the inside for pierogi-style dumplings if you want to take it that step further."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
