INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_088_1','rcp_world_088',1,'{"steps":["Soak the dried chillies in hot water for fifteen minutes until soft.","Blend the softened chillies with the vinegar until mostly smooth.","Whisk the oil, ground sesame, paprika and cumin into the chilli blend.","Add the crushed garlic and season with salt and pepper.","Taste and adjust: more vinegar for sharpness, more oil to round it out.","Cut whatever you are grilling into evenly sized pieces.","Toss thoroughly in the marinade, coating every surface well.","Cover and refrigerate for at least two hours, longer if possible.","Thread onto skewers, leaving small gaps between pieces.","Grill over medium-high heat, turning often, until charred and cooked through."],"blocks":[{"id":"blk_world_088_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The vinegar in this marinade is doing structural work, not just flavour. It is what tenderises whatever you are grilling and helps the spice paste actually cling.","Give it a proper marinating time. A rushed thirty minutes barely reaches the surface of what is being grilled."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
