INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_089','World kitchen 089','Colombian-Style Lentil and Sesame Filling','colombian-lentil-sesame-empanada-filling','A well-spiced, well-drained lentil filling in the Colombian tradition, dry enough to hold inside pastry without leaking.',15,30,6,'["vegetarian","vegan"]','published','rcv_world_089_1','2026-08-16T09:00:00Z','Colombian-Style Lentil and Sesame Filling — True Grit','A well-spiced, well-drained lentil filling in the Colombian tradition, dry enough to hold inside pastry without leaking.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','empanada filling, lentils, Colombian, sesame',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Colombian-Style Lentil and Sesame Filling, made with True Grit staples',NULL,'Colombian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_089_1','rcp_world_089',1,'{"steps":["Rinse the lentils and simmer them in the water until fully soft.","Drain thoroughly, since excess liquid will make the filling too wet.","Warm the oil and cook the onion and tomato together until soft.","Add the garlic and cumin, stirring one minute until fragrant.","Add the drained lentils and mash them lightly in the pan.","Cook over medium heat, stirring often, until visibly drier and thicker.","Continue for about ten minutes, until the mixture holds its shape.","Season generously with salt and pepper, tasting as it reduces.","Stir the roasted sesame seeds through in the last minute of cooking.","Cool completely before using as a pastry filling, or serve warm as is."],"blocks":[{"id":"blk_world_089_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Any filling destined for pastry has to be dry, or it will burst its wrapper the moment it hits hot oil or an oven. Cook this one down until it is closer to paste than stew.","This is offered as a versatile filling, spoonable on its own over rice or daliya, or ready to fold into pastry if you want to take it that step further."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_089','Colombian-Style Lentil and Sesame Filling','colombian-lentil-sesame-empanada-filling','A well-spiced, well-drained lentil filling in the Colombian tradition, dry enough to hold inside pastry without leaking.','empanada filling, lentils, Colombian, sesame');
