INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_090','World kitchen 090','Kenyan-Style Stiff Daliya Ugali','kenyan-sesame-daliya-ugali-style','A stiff, sliceable porridge in the ugali tradition, using finely ground daliya where maize flour would normally go.',5,25,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_090_1','2026-08-16T09:00:00Z','Kenyan-Style Stiff Daliya Ugali — True Grit','A stiff, sliceable porridge in the ugali tradition, using finely ground daliya where maize flour would normally go.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','ugali style, stiff porridge, daliya, Kenyan',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Kenyan-Style Stiff Daliya Ugali, made with True Grit staples',NULL,'Kenyan');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_090_1','rcp_world_090',1,'{"steps":["Bring two-thirds of the water to a rolling boil in a heavy pot.","Add the salt to the boiling water before any grain goes in.","Mix the remaining water with the daliya to a smooth, thin paste.","Pour the paste into the boiling water while stirring vigorously.","Switch to a wooden spoon once it thickens past whisking easily.","Cook, stirring and beating hard, for fifteen to twenty minutes.","The mixture should stiffen considerably and pull away from the pot sides.","Beat firmly against the pan sides to work out any remaining lumps.","Turn out onto a plate while still hot, shaping it into a rounded mound.","Let it firm for a couple of minutes, then slice to serve alongside a stew."],"blocks":[{"id":"blk_world_090_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Ugali is meant to be stiff enough to hold its shape when turned out and sliced, not spoonable like a soft porridge. Cooking it long enough is what gets you there.","Add the grain gradually while beating hard, never all at once, or it clumps into hard lumps that will not smooth out no matter how long you cook it."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_090','Kenyan-Style Stiff Daliya Ugali','kenyan-sesame-daliya-ugali-style','A stiff, sliceable porridge in the ugali tradition, using finely ground daliya where maize flour would normally go.','ugali style, stiff porridge, daliya, Kenyan');
