INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_091','World kitchen 091','Nigerian-Style Steamed Field Pea Pudding','nigerian-sesame-daliya-moin-moin-style','Skinned, blended field peas steamed in small parcels until they set into a firm savoury pudding, borrowing the moin moin technique.',30,60,6,'["vegetarian","vegan","gluten free"]','published','rcv_world_091_1','2026-08-16T09:00:00Z','Nigerian-Style Steamed Field Pea Pudding — True Grit','Skinned, blended field peas steamed in small parcels until they set into a firm savoury pudding, borrowing the moin moin technique.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','moin moin style, steamed pudding, field peas, Nigerian',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/white-field-peas.webp','Nigerian-Style Steamed Field Pea Pudding, made with True Grit staples',NULL,'Nigerian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_091_1','rcp_world_091',1,'{"steps":["Drain the soaked, skinned peas and blend them with the onion and pepper.","Add water sparingly, blending only until thick and smooth, not runny.","Stir in the oil and salt, mixing thoroughly through the batter.","Set up a steamer or a large pot with a rack and simmering water.","Divide the batter between small heatproof bowls or wrapped leaf parcels.","Cover each container loosely to allow the steam to circulate.","Arrange the containers on the rack above the simmering water.","Cover the pot tightly and steam for fifty to sixty minutes.","Check the water level halfway through and top up with boiling water.","Test one for a firm, set texture before unmoulding and serving warm."],"blocks":[{"id":"blk_world_091_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The blended mixture needs to be thick, not watery, or the finished pudding will never set firm enough to slice. Add water in small increments and stop as soon as it blends smoothly.","Steam with a properly tight lid and check the water level partway through. A pot that runs dry ruins the texture and can scorch the parcels."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_091','Nigerian-Style Steamed Field Pea Pudding','nigerian-sesame-daliya-moin-moin-style','Skinned, blended field peas steamed in small parcels until they set into a firm savoury pudding, borrowing the moin moin technique.','moin moin style, steamed pudding, field peas, Nigerian');
