INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_092_1','rcp_world_092',1,'{"steps":["Cream the butter and sugar together until pale and fluffy.","Beat in the egg and orange blossom water until fully combined.","Combine the flour and baking powder, then fold them through the wet mixture.","Bring the dough together gently, stopping once it is just combined.","Roll the dough into walnut-sized balls between your palms.","Roll each ball firmly in the sesame seeds until fully coated.","Flatten gently with your palm onto a lined baking tray.","Space them with room to spread slightly during baking.","Bake at 175C for fourteen to fifteen minutes until the edges colour.","Cool on the tray for five minutes before moving to a rack."],"blocks":[{"id":"blk_world_092_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["These are built for dunking, which means a crisp edge and a slightly softer centre rather than an all-the-way-through crunch.","Roll each ball firmly in the sesame seeds before flattening. Pressing them in after flattening leaves patchy, uneven coverage."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_092','Moroccan Mint Tea Sesame Cookies','moroccan-mint-tea-style-sesame-cookies','A simple sesame-crusted cookie meant for dunking in mint tea, crisp at the edge and slightly tender at the centre.','sesame cookies, Moroccan, mint tea biscuits, wheat flour');
