INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_093_1','rcp_world_093',1,'{"steps":["Warm the oil and cook the onion until soft and lightly coloured.","Stir in the tomato paste and cook for one minute until darkened.","Add the blended tomatoes and cook down for ten minutes until thickened.","Add the carrot, chilli, bay leaf and stock, bringing to a simmer.","Cook for ten minutes until the carrot is nearly tender.","Add the cabbage and cook a further five minutes.","Stir the daliya into the sauce and vegetables, coating it evenly.","Cover tightly and cook on the lowest heat for eighteen minutes.","Resist stirring in the final few minutes so the base can lightly crust.","Rest briefly, then serve with the lightly crusted grain from the base on top."],"blocks":[{"id":"blk_world_093_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The base of the pot is meant to catch and lightly crust, similar to the prized bottom layer in a proper thiebou. Do not stir it away in the final minutes.","Vegetables go in at different stages by how long they take, so nothing ends up mush while something else stays raw."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_093','Senegalese-Style Tomato Daliya','senegalese-sesame-daliya-thiebou-style','A one-pot tomato daliya borrowing the layered vegetable technique of thiebou djeun, with the grain finished until it takes on a crust at the base.','thiebou style, tomato rice style, daliya, Senegalese');
