INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_094','World kitchen 094','Argentinian-Style Sesame Chimichurri','argentinian-sesame-chimichurri','A chopped herb sauce with roasted sesame folded in, rested rather than blended smooth so the texture stays rustic.',15,0,10,'["vegetarian","vegan","gluten free"]','published','rcv_world_094_1','2026-08-16T09:00:00Z','Argentinian-Style Sesame Chimichurri — True Grit','A chopped herb sauce with roasted sesame folded in, rested rather than blended smooth so the texture stays rustic.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','chimichurri, sesame, Argentinian, herb sauce',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Argentinian-Style Sesame Chimichurri, made with True Grit staples',NULL,'Argentinian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_094_1','rcp_world_094',1,'{"steps":["Chop the parsley finely by hand, gathering and chopping in batches.","Chop the oregano finely if using fresh, or measure the dried.","Combine the parsley, oregano, garlic and chilli flakes in a bowl.","Stir in the roasted sesame seeds, distributing them evenly.","Add the vinegar first and stir it through the herb mixture.","Pour in the sesame oil gradually, stirring as you add it.","Season with salt and pepper, tasting for a balanced sharpness.","Cover and rest at room temperature for at least an hour.","Stir again before serving, since the oil will separate slightly.","Spoon generously over grilled vegetables or steamed daliya to serve."],"blocks":[{"id":"blk_world_094_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Chop the herbs by hand rather than blending them. A blender bruises the leaves and turns the sauce a dull, muddy green instead of a bright one.","Let it rest for at least an hour before serving. The vinegar and oil need that time to properly infuse through the chopped herbs."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_094','Argentinian-Style Sesame Chimichurri','argentinian-sesame-chimichurri','A chopped herb sauce with roasted sesame folded in, rested rather than blended smooth so the texture stays rustic.','chimichurri, sesame, Argentinian, herb sauce');
