INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_095','World kitchen 095','Spanish-Style Daliya and Potato Tortilla','spanish-daliya-tortilla-style-bake','A thick egg bake with softened potato and cooked daliya folded through, using the low-and-slow potato technique tortilla is built on.',20,30,6,'["vegetarian","gluten free"]','published','rcv_world_095_1','2026-08-16T09:00:00Z','Spanish-Style Daliya and Potato Tortilla — True Grit','A thick egg bake with softened potato and cooked daliya folded through, using the low-and-slow potato technique tortilla is built on.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tortilla espanola style, daliya, potato, Spanish',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Spanish-Style Daliya and Potato Tortilla, made with True Grit staples',NULL,'Spanish');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_095_1','rcp_world_095',1,'{"steps":["Warm the oil in a wide pan and add the potatoes and onion together.","Cook over low heat for twenty minutes, turning occasionally, until soft.","The potatoes should yield easily to a knife without browning much.","Lift the potatoes and onion out with a slotted spoon, draining the oil.","Whisk the eggs with the salt in a large bowl until just combined.","Fold the drained potatoes, onion and cooked daliya into the eggs.","Warm a little of the reserved oil in the pan over medium heat.","Pour in the mixture, spreading it evenly, and cook for five minutes.","Slide onto a plate, invert the pan over it, and flip in one motion.","Return to the pan and cook the second side for a further four minutes."],"blocks":[{"id":"blk_world_095_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The potatoes are cooked low and slow in plenty of oil until soft, not fried hard and crisp. That gentle cooking is what gives a proper tortilla its custardy interior.","Flipping the tortilla whole is the traditional test of nerve. A plate held firmly over the pan and a confident, single motion make it far less risky than it looks."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_095','Spanish-Style Daliya and Potato Tortilla','spanish-daliya-tortilla-style-bake','A thick egg bake with softened potato and cooked daliya folded through, using the low-and-slow potato technique tortilla is built on.','tortilla espanola style, daliya, potato, Spanish');
