INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_096','World kitchen 096','Italian Sesame Taralli Rings','italian-sesame-taralli-rings','Small crunchy rings that are boiled briefly before baking, the same two-stage method that gives bagels their chew.',30,25,20,'["vegetarian"]','published','rcv_world_096_1','2026-08-16T09:00:00Z','Italian Sesame Taralli Rings — True Grit','Small crunchy rings that are boiled briefly before baking, the same two-stage method that gives bagels their chew.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','taralli, sesame rings, Italian, wine-based dough',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/wheat-flour.webp','Italian Sesame Taralli Rings, made with True Grit staples',NULL,'Italian');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_096_1','rcp_world_096',1,'{"steps":["Combine the flour, salt and cracked pepper in a large bowl.","Add the wine and oil, bringing the mixture into a firm dough.","Knead for eight minutes until smooth, then knead in the sesame seeds.","Rest the dough, covered, for thirty minutes at room temperature.","Pinch off small pieces and roll each into a thin rope by hand.","Join the ends of each rope into a small ring, pinching firmly to seal.","Bring a large pot of water to a gentle boil and drop in a batch.","Boil each ring until it rises to the surface, about one minute.","Lift out with a slotted spoon and drain briefly on a clean cloth.","Arrange on a tray and bake at 180C for twenty-five minutes until hard and golden."],"blocks":[{"id":"blk_world_096_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Boiling before baking sets the surface of the dough, which is what gives taralli their characteristic hard, glassy crust rather than a soft one.","Roll the ropes evenly and pinch the ends firmly when forming the rings. A weak seam is the first place a tarallo splits open in the boiling water."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_096','Italian Sesame Taralli Rings','italian-sesame-taralli-rings','Small crunchy rings that are boiled briefly before baking, the same two-stage method that gives bagels their chew.','taralli, sesame rings, Italian, wine-based dough');
