INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_097','World kitchen 097','German-Style Sesame Red Lentil Frikadellen','german-sesame-red-lentil-frikadellen','Pan-fried patties built on mashed red lentils and toasted sesame, shaped and rested before frying so they hold together.',20,20,5,'["vegetarian","vegan"]','published','rcv_world_097_1','2026-08-16T09:00:00Z','German-Style Sesame Red Lentil Frikadellen — True Grit','Pan-fried patties built on mashed red lentils and toasted sesame, shaped and rested before frying so they hold together.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','frikadellen style, patties, red lentils, sesame, German',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','German-Style Sesame Red Lentil Frikadellen, made with True Grit staples',NULL,'German');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_097_1','rcp_world_097',1,'{"steps":["Mash the cooked, drained lentils roughly with a fork in a bowl.","Warm a little oil and cook the onion until soft and lightly golden.","Combine the lentils, cooked onion, sesame seeds and breadcrumbs.","Add the egg and mustard, mixing until the mass holds together.","Season generously with salt and pepper, tasting the raw mixture.","Shape into patties about two centimetres thick with damp hands.","Chill the shaped patties for at least twenty minutes before frying.","Warm the remaining oil in a wide pan over medium-high heat.","Fry the patties for four minutes per side until deeply golden.","Drain briefly on paper and serve warm with mustard on the side."],"blocks":[{"id":"blk_world_097_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Resting the shaped patties in the fridge before frying is what stops them falling apart in the pan. Skipping that rest is the most common reason these break up.","Fry in a properly hot pan with enough oil to shallow-fry, not a dry non-stick surface. A dry pan gives pale, steamed patties rather than a proper crust."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_097','German-Style Sesame Red Lentil Frikadellen','german-sesame-red-lentil-frikadellen','Pan-fried patties built on mashed red lentils and toasted sesame, shaped and rested before frying so they hold together.','frikadellen style, patties, red lentils, sesame, German');
