INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_098','World kitchen 098','Vietnamese-Style Caramel Sesame Daliya','vietnamese-sesame-caramel-daliya','A dry caramel cooked to the edge of burning, then daliya simmered in it until the grain takes on a deep, savoury-sweet colour.',10,30,4,'["vegetarian","vegan","gluten free"]','published','rcv_world_098_1','2026-08-16T09:00:00Z','Vietnamese-Style Caramel Sesame Daliya — True Grit','A dry caramel cooked to the edge of burning, then daliya simmered in it until the grain takes on a deep, savoury-sweet colour.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','caramel style, daliya, sesame, Vietnamese, kho style',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/daliya.webp','Vietnamese-Style Caramel Sesame Daliya, made with True Grit staples',NULL,'Vietnamese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_098_1','rcp_world_098',1,'{"steps":["Heat the sugar alone in a dry, heavy pot without stirring it.","Swirl the pot occasionally as it melts and darkens towards amber.","Push it until it smells faintly of smoke, right at the edge of burning.","Carefully pour in a splash of the water, standing well back as it spits.","Stir until the hardened caramel dissolves back into a smooth liquid.","Warm the oil separately and fry the shallots until soft and fragrant.","Add the shallots and remaining water to the caramel and bring to a simmer.","Stir in the daliya and fish sauce, coating the grain in the liquid.","Cover and simmer for twenty minutes, stirring occasionally, until tender.","Finish with black pepper and roasted sesame seeds, then serve warm."],"blocks":[{"id":"blk_world_098_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The caramel is meant to go past golden into a deep amber that smells faintly of smoke, right at the edge of burnt. Pull it too early and the dish stays merely sweet.","Add liquid to the hot caramel carefully and from a distance. It spits and hardens instantly on contact, which is completely normal and settles once it heats through."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_098','Vietnamese-Style Caramel Sesame Daliya','vietnamese-sesame-caramel-daliya','A dry caramel cooked to the edge of burning, then daliya simmered in it until the grain takes on a deep, savoury-sweet colour.','caramel style, daliya, sesame, Vietnamese, kho style');
