INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_099','World kitchen 099','Moroccan Sesame Seed Bread','moroccan-sesame-seed-bread-khobz','A round, semolina-dusted daily bread with a heavy sesame crust, baked flat and torn rather than sliced.',20,30,8,'["vegetarian","vegan"]','published','rcv_world_099_1','2026-08-16T09:00:00Z','Moroccan Sesame Seed Bread — True Grit','A round, semolina-dusted daily bread with a heavy sesame crust, baked flat and torn rather than sliced.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','khobz style, Moroccan bread, sesame crust, round loaf',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/wheat-flour.webp','Moroccan Sesame Seed Bread, made with True Grit staples',NULL,'Moroccan');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_099_1','rcp_world_099',1,'{"steps":["Dissolve the yeast in the warm water and leave until it foams.","Mix the flour and salt, then add the yeast water and the oil.","Knead for ten minutes until the dough is smooth and elastic.","Prove covered in a warm place for one hour, until roughly doubled.","Knock back gently and shape into a flattish round about four centimetres thick.","Dust a tray generously with semolina and place the round on top.","Brush the surface lightly with water and scatter the sesame seeds over.","Press the seeds in gently so they stay put during baking.","Prick the surface a few times with a fork and prove a further thirty minutes.","Bake at 220C for thirty minutes until deeply golden and hollow-sounding."],"blocks":[{"id":"blk_world_099_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["This bread is torn by hand at the table, never sliced with a knife, which is part of why it is baked as a flattish disc rather than a tall loaf.","Dust the base with semolina before baking. It keeps the bottom from sticking and gives it a faint crunch that a plain tray does not."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_099','Moroccan Sesame Seed Bread','moroccan-sesame-seed-bread-khobz','A round, semolina-dusted daily bread with a heavy sesame crust, baked flat and torn rather than sliced.','khobz style, Moroccan bread, sesame crust, round loaf');
