INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at,cuisine) VALUES ('rcp_world_100','World kitchen 100','Chinese-Style Sesame Filled Sweet Dumplings','chinese-sesame-flax-tang-yuan-style','Glutinous rice dumplings filled with a sesame and sugar paste, sealed carefully so the molten centre does not burst in the water.',40,15,6,'["vegetarian"]','published','rcv_world_100_1','2026-08-16T09:00:00Z','Chinese-Style Sesame Filled Sweet Dumplings — True Grit','Glutinous rice dumplings filled with a sesame and sugar paste, sealed carefully so the molten centre does not burst in the water.','2026-08-16T09:00:00Z','usr_catalogue_system','2026-08-16T09:00:00Z','usr_catalogue_system','tang yuan style, sesame filling, sweet dumplings, Chinese',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/seeds.webp','Chinese-Style Sesame Filled Sweet Dumplings, made with True Grit staples',NULL,'Chinese');
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_world_100_1','rcp_world_100',1,'{"steps":["Mix the ground sesame, sugar and softened butter into a firm paste.","Roll the paste into small balls and chill them until firm, about thirty minutes.","Combine the glutinous rice flour with the warm water into a smooth dough.","Knead briefly until the dough is soft, pliable and free of cracks.","Divide the dough into pieces slightly larger than the chilled filling balls.","Flatten each piece and place a filling ball in the centre.","Gather the edges up and around, pinching firmly to seal completely.","Roll gently between your palms until perfectly smooth and round.","Bring a pot of water to a gentle boil and drop the dumplings in.","Cook until they float and then a further two minutes, then serve warm in their broth."],"blocks":[{"id":"blk_world_100_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["The filling is chilled and rolled into firm balls before wrapping. Soft filling is nearly impossible to seal cleanly inside the wrapper dough.","Sealing has to be complete, with no visible seam or thin patch. Any weak point in the wrapper is exactly where a dumpling bursts open in the simmering water."]}}]}','published','2026-08-16T09:00:00Z','usr_catalogue_system');
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('recipe','rcp_world_100','Chinese-Style Sesame Filled Sweet Dumplings','chinese-sesame-flax-tang-yuan-style','Glutinous rice dumplings filled with a sesame and sugar paste, sealed carefully so the molten centre does not burst in the water.','tang yuan style, sesame filling, sweet dumplings, Chinese');
